quests[55084] = { id = 55084, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bauplan: Verschlüsseltes Schwarzmarktfunkgerät", description = "<Das scheint der Bauplan für die Konstruktion eines Funkgeräts mit hochverschlüsseltem Sender zu sein.\n\nIhr müsstet den Bauplan im Rostbolzen in Pascal-K1N6s Datenbank hochladen können.>", sourceObjective = "Ladet den Bauplan in die Datenbank von Pascal-K1N6.\n\nBereitgestellter Gegenstand:", completion = "Habt Ihr einen neuen Bauplan gefunden, mein fleischiger Freund?\n\nIch werde ihn umgehend meiner Datenbank hinzufügen.", sourceObjectiveStatus = "unverified-source-field" }
quests[55087] = { id = 55087, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der drohende Sturm", description = "Während ich mich um die Übergriffe der Naga kümmere, übernimmt Lady Prachtmeer die Horde im Sturmsangtal und findet heraus, was aus unseren Spionen geworden ist.\n\nIhr findet sie in der Nähe von Burg Prachtmeer.", sourceObjective = "Meldet Euch bei Jaina Prachtmeer in der Nähe von Burg Prachtmeer in Boralus.", completion = "Es scheint, die Hordeaktivität im Sturmsangtal ist ernstzunehmender, als wir ursprünglich dachten.", sourceObjectiveStatus = "unverified-source-field" }
quests[55088] = { id = 55088, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Im Einsatz vermisst", description = "Als Shaw und ich hier angekommen sind, mussten wir feststellen, dass die meisten unserer Agenten tot waren. Die meisten, aber nicht alle.\n\nBegebt Euch ins Feld und holt so viele unserer Agenten da raus, wie Ihr finden könnt. Sie könnten mehr Informationen darüber haben, was die Horde hier in der Reißzahnfeste plant.", sourceObjective = "Helft verletzten Spionen im Sturmsangtal.", completion = "Unsere Leute sind da draußen auf eine richtig große Sache gestoßen!", sourceObjectiveStatus = "unverified-source-field" }
quests[55089] = { id = 55089, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mission auf Messers Schneide", description = "Hmm. Shaw sagte, er würde sich melden, wenn die Kommunikation wieder steht, aber das hat er nicht. Er ist wohl auf dieselben Probleme gestoßen wie unsere Spione.\n\nIch bleibe hier und sichere den Horchposten. Ihr sucht Shaw. Er ist in Richtung der Klippen oberhalb der Reißzahnfeste am oberen Teil des Wasserfalls gegangen. Aus irgendeinem Grund nennen die Peons diesen Ort \"Die Schreiende Grube\". Ich wette, dort ist es wundervoll.\n\nTut mir einen Gefallen und erstecht gegen was auch immer er kämpft, okay?", sourceObjective = "Findet Mathias Shaw in der Schreienden Grube oberhalb der Reißzahnfeste.", completion = "Sie haben die Sicherheitsvorkehrungen hier weitaus stärker als erwartet erhöht... und das aus gutem Grund.", sourceObjectiveStatus = "unverified-source-field" }
quests[55090] = { id = 55090, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine feindliche Versammlung", description = "Bevor ich abgelenkt wurde, konnte ich mehr über dieses Treffen der Horde in Erfahrung bringen: Sylvanas hat die Anführer der Horde und ihrer Verbündeten versammelt. Den Grund dafür kenne ich nicht.\n\nWir sind leider nicht in der Lage, Sylvanas anzugreifen. Dafür ist sie zu gut geschützt. Vielleicht können wir aber Informationen sammeln, die sich im weiteren Verlauf des Krieges als nützlich erweisen könnten.\n\nBleibt in Deckung und beobachtet, was dort unten vor sich geht. Ich halte nach weiteren Wachen Ausschau.", sourceObjective = "Beobachtet die Versammlung der Horde.", completion = "Baine tut mir irgendwie leid. Für ehrenhafte Leute wie ihn scheint in der Horde kein Platz mehr zu sein.\n\nSylvanas hat einen kühnen Schachzug gewagt. Wir werden sie angreifen, aber sie ist gerissen. Wir müssen die Naga zurückschlagen und unsere Truppen sammeln, bevor wir zum vernichtenden Schlag ausholen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[55092] = { id = 55092, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Störung der Macht", description = "Die Naga ziehen ihre Macht aus den Leylinien in der Nähe, und wir haben einen Weg gefunden, wie wir diese Macht ebenfalls nutzen können.\n\nZerstört ihre Geräte, bevor sie diese Macht gegen uns einsetzen können.", sourceObjective = "Zerstört 5 Leylinienakkumulatoren in Azsharas Speeren.", completion = "Hoffentlich finden wir niemals heraus, wofür sie die ganze Macht nutzen wollten.", sourceObjectiveStatus = "unverified-source-field" }
quests[55094] = { id = 55094, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kopf runter, Beine in die Hand!", description = "Der Heimweg ist ganz einfach. Wir müssen nur vorsichtig sein.\n\nNeris Überlebenstipp Nummer sechs: Immer vorbereitet sein!\n\nAuf geht's!", sourceObjective = "Folgt Neri Scharffinne.", completion = "Endlich eine kleine Erleichterung. Aber wir dürfen uns nicht beruhigt zurücklehnen. Azshara führt sicherlich noch mehr gegen uns im Schilde, als sie sich anmerken lässt.", sourceObjectiveStatus = "unverified-source-field" }
quests[55095] = { id = 55095, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufruhr", sourceObjective = "Sprecht mit Lady Jaina Prachtmeer oberhalb des Wasserfalls.", completion = "Endlich ein paar gute Neuigkeiten. Unser Champion erwacht aus dem Chaos.", sourceObjectiveStatus = "unverified-source-field" }
quests[55096] = { id = 55096, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Nachricht für meinen Vater", description = "Mein Volk ist wieder in Sicherheit... für den Augenblick.\n\nKönig Mechagon wird nicht damit aufhören, seine Armeen gegen uns zu schicken, so lange er uns nicht fürchtet.\n\nWir müssen ihm eine Nachricht schicken.\n\nKlettert auf die Spitze der Befestigungswälle und hackt einen der Projektoren meines Vaters, um das Banner des Rostbolzenwiderstands stolz erstrahlen zu lassen, sodass die ganze Insel es sieht.\n\nDas wird sicher die Aufmerksamkeit meines Vaters, König Mechagon, erregen.", sourceObjective = "Hackt einen Projektor, lasst das Emblem des Rostbolzenwiderstands erstrahlen und verteidigt es.", completion = "Der Rostbolzen sieht richtig aufgewertet aus, nicht wahr?\n\nEs ist nicht das erste Mal, dass wir ihn wieder aufbauen mussten, und es wird sicher auch nicht das letzte Mal sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[55101] = { id = 55101, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schrottplatztüfteleien für jedermann", description = "Erblickt die sagenumwobene Werkstatt von Pascal im Rostbolzen - MEINE Werkstatt!\n\nAn diesem Ort sind unzählige Erfindungen zum Leben erweckt worden, inklusive meiner allerbesten Erfindung: Pascal-K1N6!\n\nPascal-K1N6 kann alles herstellen... solange man ihm die richtigen Pläne dafür bringt.\n\nUnd da ich Euch für das sichere Zurückbringen von K1N6 zum Rostbolzen danken muss, biete ich Euch an, zu erfahren, wie man auf seine Bauplandatenbank zugreift.", sourceObjective = "Benutzt Pascal-K1N6 und stellt eine Schrottgranate her.", completion = "Pascal-K1N6 ist ein Wunderwerk der Schrottplatztüftelei! Ein Wunder des modernen Zeitalters!\n\nHabe ich schon erwähnt, dass ich ihn höchstpersönlich erfunden habe? Natürlich habe ich das.", sourceObjectiveStatus = "unverified-source-field" }
quests[55103] = { id = 55103, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ideen kommen von überall her", description = "Ich habe bei unserer ersten Begegnung den Tüftlerfunken in Euch gar nicht bemerkt.\n\nAber nun seht Euch all die Baupläne an, die Ihr entdeckt und in Pascal-K1N6s Datenbank hochgeladen habt.\n\nIch habe mich geirrt. Und darüber bin ich froh, mein aufstrebender Schrottplatztüftlerlehrling!\n\nDoch dies ist ein gefährlicher Moment in Eurer kreativen Entwicklung.\n\nIhr musst die Selbstzufriedenheit vermeiden!\n\nEs ist Zeit, loszuziehen und neue Ideen zu finden. Sprecht mit Handwerkern, die Euch inspirieren, findet heraus, wie die Bots auf der Insel funktionieren, und seid offen für neue Ideen, ganz gleich, woher sie stammen!", sourceObjective = "Findet Personen und Dinge in Mechagon, die 1 neue Ideen inspirieren können.", completion = "Ich sehe es! Das Funkeln neuer Ideen in Euren Augen...\n\nIhr seid von Euren Reisen zurückgekehrt, frisch und bereit für einen Gedankenaustausch über neue Baupläne!\n\nDas bin ich auch. Lasst uns diskutieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[55111] = { id = 55111, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kreaturenstudie: Naga der Zanj'ir", description = "<Auf der magischen Schriftrolle stehen Maedins unvollständige Notizen zu den Naga der Zanj'ir.>", sourceObjective = "Nutzt Maedins Schriftrolle, um Daten über verschiedene Kreaturen in Nazjatar zu sammeln.", sourceObjectiveStatus = "unverified-source-field" }
quests[55116] = { id = 55116, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Entziffereien", description = "Ich würde wetten, dass diese Seite voller Kauderwelsch eine verschlüsselte Nachricht ist. Wir können sie entweder nach Sturmwind schicken und unseren Codeknackern die Arbeit überlassen oder wir suchen hier nach einer Chiffre.\n\nJa, ich glaube, das machen wir. Das dürfte uns einiges an Zeit sparen.\n\nDer Anführer hier hat vermutlich genau das, wonach wir suchen. Schaltet ihn aus und durchsucht ihn. Und wenn Ihr nicht fündig werdet, ist es auch nicht schlimm. Ohne ihren Anführer werden uns die Loyalisten keine größeren Probleme mehr bereiten. Am Ende gewinnt also jeder!\n\n...Von uns, versteht sich.", sourceObjective = "Tötet Hindrik Fassner und besorgt Euch seine Chiffre.", progress = "Habt Ihr eine Chiffre gefunden? Oder eine Art Entschlüsselungsgerät?", completion = "Ein Entschlüsselungsring? Tja, mit den Klassikern liegt man vermutlich nie falsch.\n\n<Kelsey entschlüsselt die Nachricht mithilfe des Rings.>\n\nDie stammt definitiv von Aschenwind. Das Datum ist aber ziemlich alt. Der \"Kunde\", den sie erwähnt, dürfte einige Leute in Boralus sehr interessieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[55117] = { id = 55117, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Korrespondenzscharade", description = "Aschenwind stand wohl mit ihren Loyalisten in Kontakt, aber ich weiß nicht, wie ihre Befehle lauten.\n\nGeht in ihr Lager und versucht, ihre Briefe zu lesen. Vielleicht erfahren wir dadurch, wo sich Lady Aschenwind versteckt oder was sie als Nächstes geplant hat.", sourceObjective = "Findet Informationen über Lady Aschenwinds Pläne.", completion = "Ein Rezept, ein Gedicht, Frachtdokumente... Wettscheine? Oh! Das hier ist eine verschlüsselte Nachricht. Hmmm.\n\n<Kelsey reibt sich das Kinn und spielt beim Nachdenken mit einem ihrer Messer.>\n\nIch würde wetten, dass der Anführer hier eine Chiffre hat. Warum stattet Ihr ihm nicht einen Besuch ab und besorgt uns diesen Codeschlüssel?", sourceObjectiveStatus = "unverified-source-field" }
quests[55118] = { id = 55118, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ungeklärte Angelegenheiten", description = "Unser Feldzug gegen die Horde läuft gut, aber es gibt immer noch ein paar ungeklärte Angelegenheiten, um die wir uns kümmern müssen.\n\nLady Aschenwind wurde aus Tol Dagor befreit... von der Horde. Wir kennen weder ihren Aufenthaltsort noch ihre Pläne. Ich habe Kelsey losgeschickt, um ein paar Loyalisten der Aschenwinds aufzuspüren und Antworten zu bekommen. Sie ist fündig geworden, hat aber Verstärkung angefordert.\n\nSie erwartet Euch in Freihafen.", sourceObjective = "Trefft Euch mit Kelsey Stahlfunken in Freihafen.", completion = "Ich habe ein ganzes Nest dieser Typen gefunden!\n\nSeid Ihr bereit, sie gemeinsam mit mir auszuschalten?", sourceObjectiveStatus = "unverified-source-field" }
quests[55119] = { id = 55119, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Melde mich zum Dienst!", description = "Nun, allem Anschein nach gab es von Aschenwind länger keine Nachrichten mehr, aber diese Sache mit dem \"Kunden\" könnte ein Problem darstellen.\n\nIhr habt heute hervorragende Arbeit geleistet, {name}. Diese Loyalisten dürften uns eine Zeit lang keine Probleme mehr bereiten, hehe.\n\nIch werde mich auf den Rückweg machen. Bringt Ihr diesen Brief zum Hochkommandanten.", sourceObjective = "Meldet Euch bei Halford Wyrmbann in Boralus.", completion = "<Wyrmbann zeigt auf den Brief.>\n\nWenn das Aschenwinds letzte Nachricht war, ist ihr Treffen mit diesem mysteriösen \"Kunden\" vielleicht nicht wie geplant verlaufen.\n\nWir werden die Sache im Auge behalten. In der Zwischenzeit sprecht Ihr wohl besser mit unserem... Gast.", sourceObjectiveStatus = "unverified-source-field" }
quests[55121] = { id = 55121, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mardivas' Labor", description = "<Viele Seiten drehen sich um Notizen zu einem Experiment. Danach kommt ein hastig geschriebener Tagebucheintrag.>\n\nEndlich trägt meine Erforschung der Grundelemente Früchte!\n\nWenn man die richtigen Grundreagenzien mit etwas arkaner Macht zusammen verwendet, kann man die Essenz der Elemente so kombinieren, dass Leben entsteht!\n\nEs ist noch weitere Forschung nötig, um festzustellen, was die verschiedenen Kombinationen von Elementen hervorbringen.\n\n<Hier endet der Text.>", sourceObjective = "Aktiviert den Elementaressenzenamalgamator in Mardivas' Labor.", progress = "<Die restlichen Seiten sind voller Geschwafel und seltsamen Kritzeleien.>", completion = "<Die Magie des Systems scheint versiegt zu sein. Vielleicht kann es nach einiger Zeit erneut genutzt werden.>", sourceObjectiveStatus = "unverified-source-field" }
quests[55122] = { id = 55122, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Murlocmanie", description = "Es freut mich, dass Ihr es in einem Stück herausgeschafft habt.\n\nWenn man sich das Schiffswrack in der Nähe ansieht, sollte man meinen, dass die verschollene Expedition hier gestrandet ist.\n\nDoch bevor die anderen Überlebenden sich erholt haben, können wir nicht von hier weg.\n\nDummerweise haben Murlocs sich all unsere Vorräte geschnappt! Dieses lästige Ungeziefer...\n\nIhr müsst genug Erste-Hilfe-Vorräte zurückholen, um die Verwundeten zu versorgen.\n\nDanach können wir nach der verschollenen Expedition suchen.", sourceObjective = "Holt 6 Erste-Hilfe-Kästen von Murlocs zurück.", progress = "Habt Ihr die Erste-Hilfe-Kästen zurückgeholt? Unterschätzt die Murlocs bloß nicht.", completion = "Ausgezeichnete Arbeit. Helfen wir den Überlebenden, wieder auf die Beine zu kommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[55123] = { id = 55123, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jagdsaison" }
quests[55124] = { id = 55124, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wiedergutmachung", description = "Champion! Ich komme mit einer dringenden Bitte von Baine Bluthuf zu Euch. Er möchte sich mit Euch in Raubhafen treffen, weil er Eure Hilfe braucht. Es geht um eine... heikle Angelegenheit.\n\nIhr dürft niemandem davon erzählen, {class}. \n\nMögen die Ahnen über Euch wachen.", sourceObjective = "Trefft Euch mit Baine Bluthuf in Raubhafen im Tiragardesund.", completion = "Ihr seid hier.\n\nGut, dann können wir gleich zur Sache kommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[55125] = { id = 55125, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jagdsaison" }
quests[55136] = { id = 55136, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ihre Hundstage sind vorbei", description = "<Die Weidenbestie stupst den leblosen Körper des Hundes sanft mit der Schnauze an.\n\nDie Kreatur beginnt leise zu winseln und kommt an Eure Seite.\n\nSie wedelt hoffnungsvoll mit ihrem knochigen Schwanz.>", sourceObjective = "Geht mit der Weidenbestie Gassi.", progress = "Was ist das...? Ich sehe, Ihr habt meine Schlüssel gefunden, doch...", completion = "Oh... Oh nein, heilige Gezeiten... nein...", sourceObjectiveStatus = "unverified-source-field" }
quests[55137] = { id = 55137, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Für die Horde", description = "Danke, dass Ihr mich an meinem Thron trefft, {name}.\n\nJetzt, wo wir uns mit der Horde zusammengetan ham, brauch ich fähige Champions, die die Macht der Zandalari vertret'n. \n\nIch will, dass Ihr einer von ihnen seid, {name}. Begebt Euch nach Orgrimmar und trefft dort den Botschafter.\n\nWir ham hinter Euch 'n Portal vorbereitet. Wenn Ihr bereit seid, betretet es und Ihr gelangt in 'ne neue Welt.\n\nVergesst nich': Ihr beugt Euch allein dem Thron von Zandalar. Geht mit erhob'nem Haupt, {name}.", sourceObjective = "Trefft Botschafter Schwarzwacht in der Botschaft von Orgrimmar.", completion = "Seid Ihr der Neue? Dann soll ich Euch willkommen heißen. Hier, nehmt diesen Brief.\n\n<Schwarzwacht seufzt entnervt.>", sourceObjectiveStatus = "unverified-source-field" }
quests[55138] = { id = 55138, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fremder in einem fremden Land", description = "Hallo, ich bin Botschafter Schwarzwacht.\n\nEs ist mir eine Ehre, Euch in Orgrimmar willkommen zu heißen, {race}.\n\n<Er lächelt gekünstelt.>\n\nNun, da sich ein Leben voller Abenteuer vor Euch auftut, seid versichert, dass... ähm...\n\nWisst Ihr was? Ich habe diese Begrüßung heute den ganzen Tag immer wieder abgespult. Mir reicht's.\n\nSprecht mit Chromie auf dem Stundenglas. Und dann sprecht mit Eurem Abgesandten. Kusch!", sourceObjective = "Findet die Tafel mit den Befehlen des Kriegshäuptlings in Orgrimmar.", progress = "Das Land hier is' viel weniger... fruchtbar als Zandalar.", completion = "Es is' soweit. Wir stürz'n uns ins Abenteuer, um Ruhm und Ehre für die Zandalari und die Horde zu erring'n!\n\nMög'n die Loa mit Euch sein, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[55142] = { id = 55142, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Für die Allianz", description = "Danke für Euer Kommen, {name}.\n\nIch brauche jemanden, der unsere Loyalität und unsere Hingabe zu unserem neu geschmiedeten Bund mit der Allianz in Sturmwind demonstriert.\n\nIch habe Yvia und ihre Magier angewiesen, im Sanktum der Weisen ein Portal in die Hauptstadt für Euch vorzubereiten. Wenn Ihr dort ankommt, geht zur Botschaft von Sturmwind und trefft Euch mit Botschafter Moorgard.\n\nIhr werdet auf der langen Reise, die vor Euch liegt, vielen Herausforderungen begegnen. Vergesst nicht Eure Herkunft und macht unser Volk stolz!", sourceObjective = "Nehmt das Portal nach Sturmwind im Sanktum der Weisen und trefft Euch mit Botschafter Moorgard in der Botschaft von Sturmwind.", completion = "Da seid Ihr ja! Ihr müsst {name} sein. Wir haben Euch erwartet.", sourceObjectiveStatus = "unverified-source-field" }
quests[55146] = { id = 55146, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fremder in einem fremden Land", description = "Willkommen in Sturmwind, {race}. Ich lade Euch ein, unsere prächtige Stadt zu erkunden. Da Ihr aus Kul Tiras seid, würde ich vorschlagen, die Docks zu besichtigen. Dort liegt unsere majestätische Flotte vor Anker. Ich wäre erstaunt, wenn Ihr davon nicht beeindruckt wärt!\n\nAber das kann warten. Ein Bronzedrache wollte Euch sprechen. Sie sitzt unter dem Baum in der Nähe, ausgerechnet auf einem Stundenglas!\n\nUnd danach erwartet Euch ein Abgesandter von Kul Tiras, der Euch in der Stadt willkommen heißen will. Klingt, als hättet Ihr einen langen Tag vor Euch!\n\nIch wünsche einen angenehmen Aufenthalt!", sourceObjective = "Findet Chromie in Sturmwind.", progress = "Wie gefällt es Euch in Sturmwind?", completion = "Wohin auch immer es Euch verschlägt, Ihr solltet wissen, dass Kul Tiras hinter Euch steht.", sourceObjectiveStatus = "unverified-source-field" }
quests[55148] = { id = 55148, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückgewinnungsturm" }
quests[55153] = { id = 55153, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Konstruktionskollaboration", description = "Konstruktionsprojekte sind überall auf der Insel zu finden. Ihr werdet einige selbst fertigstellen können, aber bei den größeren Projekten werdet Ihr Hilfe benötigen.\n\nFragt herum und seht, woran andere bereits arbeiten, oder Ihr macht Euch allein auf und findet ein Projekt, das Euch interessiert.\n\nKonstruktionsprojekte verändern ihren Standort und ändern sich manchmal sogar von einem Tag auf den anderen, also haltet während Eurer Erkundung Ausschau nach neuen Projekten.\n\nWenn Ihr erfahren möchtet, welche Konstruktionsprojekte am aktuellen Tag verfügbar sind, fragt mich einfach!", sourceObjective = "Findet ein Konstruktionsprojekt in Mechagon und helft bei seinem Aufbau.", completion = "Ah, ich erinnere mich an mein erstes Konstruktionsprojekt...\n\n<Waren seufzt wehmütig.>\n\nIch frage mich, wo ich diesen dampfbetriebenen Schnuller hingeräumt habe?", sourceObjectiveStatus = "unverified-source-field" }
quests[55171] = { id = 55171, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausgespäht", description = "Die Angriffe der Naga mehren sich, aber das ist noch nicht alles, womit wir uns herumschlagen müssen. Wir haben Berichte über vermehrte Hordeaktivitäten in der Nähe der Reißzahnfeste im Sturmsangtal erhalten.\n\nSchickt Späher aus. Wir müssen herausfinden, was die Horde da treibt.", sourceObjective = "Schließt die Mission \"Spionage in der Reißzahnfeste\" ab", completion = "Verdammt. Die meisten unserer Späher haben sich noch nicht wie vorgesehen zurückgemeldet. Was immer die Horde auch vorhat, es bedeutet nichts Gutes für uns.", sourceObjectiveStatus = "unverified-source-field" }
quests[55173] = { id = 55173, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nordwärts", description = "Die Stacheleber haben den Rest der Expedition in den Norden entführt.\n\nIch habe sie über Opfer für eine Art Ritual reden hören...\n\nBitte, Ihr müsst sie retten!", sourceObjective = "Seht Euch weiter nördlich nach Austin Haxwart um.", completion = "Ich habe sowohl gute als auch sehr, sehr schlechte Neuigkeiten.", sourceObjectiveStatus = "unverified-source-field" }
quests[55174] = { id = 55174, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grillfleisch", description = "Alaria ist schon fast verhungert. Sie muss etwas essen!\n\nTötet ein paar Wildtiere in der Nähe und bringt mir das Fleisch zum Kochen.\n\nWenn wir dafür sorgen, dass es Alaria wieder besser geht, kann sie uns vielleicht erzählen, was mit den anderen geschehen ist.\n\nIch bleibe hier und versorge ihre Wunden.", sourceObjective = "Beschafft 5 Stücke rohes Fleisch von Wildtieren um das verlassene Lager und bereitet es am Lagerfeuer zu.", progress = "Bitte... ich brauche... Essen...", completion = "<Alaria verschlingt das von Euch zubereitete Fleisch.>\n\nBeim Licht... Es geht mir gleich viel besser.\n\nIhr müsst Euch beeilen... Stacheleber haben den Expeditionstrupp mitsamt dem Sohn von Kapitänin Garrick entführt!", sourceObjectiveStatus = "unverified-source-field" }
quests[55175] = { id = 55175, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Immer der Nase nach", description = "Mein Volk kennt viele Geheimnisse dieses Orts. Falls Ihr Euch als würdige Verbündete erweist, werdet auch Ihr in sie eingeweiht werden.\n\nAber zunächst müssen wir uns in Mezzameer neu aufstellen. Dort haben wir immerhin eine Stellung gegen die Flut.", sourceObjective = "Reist mit Okani nach Mezzameer.", completion = "Bisher haben sich diese Ankoaner als eindrucksvolle Verbündete erwiesen.", sourceObjectiveStatus = "unverified-source-field" }
quests[55177] = { id = 55177, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Zerreißprobe", description = "Ich fühle mich seltsam... irgendwie matt. Als ob etwas meine gesamte Existenz beeinflusst.\n\nWürdet Ihr mich begleiten, {name}? Es kann sein, dass ich Eure Hilfe brauche. Im schlimmsten Fall könnt Ihr somit Zeuge sein, falls etwas Tragisches passiert.", sourceObjective = "Sprecht mit Delormi, wenn Ihr bereit seid aufzubrechen, um die Störung zu untersuchen.", completion = "Das sieht nicht gut aus...", sourceObjectiveStatus = "unverified-source-field" }
quests[55179] = { id = 55179, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vergeltungsmaßnahmen", description = "Meister Shaw hat eine Gruppe von Allianzspionen auf die Basis der Horde angesetzt, die sie im Sturmsangtal errichtet haben. Als unsere Spione sich nicht mehr zurückgemeldet haben, ist er zusammen mit Kelsey Stahlfunken ins Tal gegangen, um zu sehen, was mit ihnen passiert ist.\n\nNun meldet sich Meister Shaw seinerseits nicht mehr.\n\nIch brauche also jemanden, der ins Tal geht, unsere vermissten Leute ausfindig macht und ihnen die Unterstützung gewährt, die sie anscheinend dringend brauchen.", sourceObjective = "Findet Kelsey Stahlfunken im Sturmsangtal.", completion = "Wir wussten, dass jemand vorbeischauen würde, wenn wir uns nicht zurückmelden. Mit Euch als Verstärkung hat die Horde gegen uns keine Chance.\n\nShaw ist weiter vorne im Tal und versucht herauszufinden, was in der Reißzahnfeste vor sich geht. Meinerseits habe ich versucht, das Chaos hier in Grenzen zu halten. Wie sieht's aus? Wollt ihr mir dabei helfen?", sourceObjectiveStatus = "unverified-source-field" }
quests[55182] = { id = 55182, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die fehlenden Bauteile", description = "Meister Shaw will, dass ich die Horchposten wieder aufbaue, die die Horde zerstört hat, als sie dieses Gebiet für wer weiß was vorbereitet haben.\n\nIch konnte fast genug Bauteile für wenigstens einen Posten bergen, aber mir fehlen noch ein paar.\n\nWir haben Glück: Ich habe die Arbeiter dabei beobachtet, wie sie Teile der zerstörten Gerätschaften aufgesammelt haben. Holt sie uns zurück und dann erledige ich den Rest.", sourceObjective = "Sammelt Geborgene Teile von den Streitkräften der Horde.", progress = "Ich bin ja so aufgeregt! Ich liebe es einfach, mit unserer Spionagetechnologie zu arbeiten! Habt Ihr gefunden, was wir brauchen?", completion = "Ja! Das ist genau das, was ich brauche.", sourceObjectiveStatus = "unverified-source-field" }
quests[55183] = { id = 55183, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf in höhere Lagen", description = "Uns bleibt nur diese eine Gelegenheit, unser Kommunikationsnetzwerk wiederherzustellen. Also müssen wir uns den richtigen Standort aussuchen, und wie es der Zufall will, habe ich schon den perfekten Kandidaten gefunden!\n\nWährend Ihr da drüben beschäftigt wart, habe ich für etwas Tarnung gesorgt und bereits den Großteil der Ausrüstung dort hoch geschafft.\n\nWas denn? Habt Ihr etwa gedacht, dass ich in Eurer Abwesenheit hier bloß auf meinem faulen Hintern sitze und meine Messerchen poliere?\n\nJa, okay, das habe ich natürlich auch gemacht. Wie dem auch sei, wir treffen uns oben auf dem Hügel!", sourceObjective = "Trefft Kelsey Stahlfunken auf dem Hügel südlich der Reißzahnfeste.", completion = "Wenn wir den Horchposten wieder aufgebaut haben, werden wir nicht genug Reichweite haben, um Boralus zu erreichen, aber immer noch genug, um uns mit Meister Shaw ins Verbindung zu setzen!", sourceObjectiveStatus = "unverified-source-field" }
quests[55184] = { id = 55184, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schattenmagie der Stacheleber", description = "Die Stacheleber sind primitive und wilde Tiere. Normalerweise setzen sie kaum mehr als geomantische Magie ein.\n\nAber diese Sorte Stacheleber scheint mit Schattenmagie zu experimentieren. Wir müssen sie aufhalten.\n\nTötet die Stacheleber im Höhlenbau. Sie dürfen diese Magie nicht auf der Insel verbreiten!", sourceObjective = "Tötet 7 Stacheleber im Dornendickicht der Stacheleber.", completion = "Gute Arbeit. Ich hoffe, dass diese Stacheleber verstanden haben, dass die Nekromantie ihnen keinen Weg zur Macht bietet.", sourceObjectiveStatus = "unverified-source-field" }
quests[55185] = { id = 55185, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lauscher auf!", description = "Okay! Sobald hier alles läuft, sollten wir in der Lage sein, Nachrichten zu versenden! Zumindest innerhalb des Tals.\n\nEs wird nicht ganz einfach, aber ich habe mir die Anleitung für dieses Gerät komplett durchgelesen.\n\n<Kelsey klopft mit der flachen Hand auf das Gehäuse der Abhöranlage.>\n\nIch schraube dieses Ding wieder zusammen. Kümmert Ihr Euch um die Horde.", sourceObjective = "Verteidigt Kelsey Stahlfunken im Sturmsangtal.", completion = "Ha! ich wusste, dass ich dieses Ding in Rekordzeit zum Laufen bringen kann.\n\nHmm. Aber Meister Shaw antwortet nicht auf mein Signal. Das ist gar nicht gut.", sourceObjectiveStatus = "unverified-source-field" }
quests[55186] = { id = 55186, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nieder mit den Stachelebern", description = "Soweit ich es verstehe, führen die Stacheleber ein Schattenritual an einem der Expeditionsmitglieder durch.\n\nIhr Anführer ist Geofürst Grek'og. Er ist derjenige, der unserem Freund das Leben entziehen will.\n\nTötet Grek'og und rettet das gefangene Expeditionsmitglied. Vielleicht weiß er, wohin die anderen gebracht wurden.", sourceObjective = "Tötet Geofürst Grek'og.", completion = "Ich danke Euch, Ihr habt mir das Leben gerettet! Die haben gesagt, das würde eine ganz gewöhnliche Expedition werden.\n\nDas war sie absolut NICHT! Und ich könnte nicht glücklicher sein!", sourceObjectiveStatus = "unverified-source-field" }
quests[55188] = { id = 55188, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Zerreißprobe", description = "Ich fühle mich seltsam... irgendwie matt. Als ob etwas meine gesamte Existenz beeinflusst.\n\nWürdet Ihr mich begleiten, {name}? Es kann sein, dass ich Eure Hilfe brauche. Im schlimmsten Fall könnt Ihr somit Zeuge sein, falls etwas Tragisches passiert.", sourceObjective = "Sprecht mit Delormi, wenn Ihr bereit seid aufzubrechen, um die Störung zu untersuchen.", completion = "Das sieht nicht gut aus...", sourceObjectiveStatus = "unverified-source-field" }
quests[55193] = { id = 55193, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Späh-o-Matik 5000", description = "Ihr seht aus wie <ein/eine:r> {race}, <der/die:r> Hilfe braucht, um die verstreuten Mitglieder unserer Allianzexpedition zu finden!\n\nEin Glück, dass Ihr zufällig mich, den meisterhaften Erfinder Lindie Sprungfeder, gerettet habt!\n\nMeine Späh-o-Matik 5000 ist einsatzbereit. Sie erhebt sich in die Lüfte, von wo aus man das ganze Gebiet überblicken kann.\n\nIch überlasse Euch die ehrenhafte Aufgabe. Benutzt meine Späh-o-Matik 5000, um den Rest der Expedition zu finden!", sourceObjective = "Benutzt die Späh-o-Matik 5000, um Henry Garrick zu finden.", progress = "Wartet kurz, ich ändere die Größe der Späh-o-Matik, dann könnt Ihr darauf reiten!", completion = "Mit einer kleinen Größenänderung lässt sich doch jedes Problem lösen! Wir müssen etwas finden, um diese Untoten plattzumachen!", sourceObjectiveStatus = "unverified-source-field" }
quests[55194] = { id = 55194, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Vorräte aufstocken", description = "Rüstmeisterin Richter konnte einige Vorräte aus den Wracks auf dieser Insel ergattern.\n\nWieso schaut Ihr nicht bei ihr vorbei und seht, ob sie etwas Nützliches für Euch hat?\n\nFür das, was uns bevorsteht, solltet Ihr gut gewappnet sein.", sourceObjective = "Kauft irgendeinen Gegenstand bei Rüstmeisterin Richter und verkauft einen beliebigen Gegenstand an sie.", progress = "Rüstmeisterin Richter sollte ein paar nützliche Vorräte für Euch haben.", completion = "Habt Ihr Euch ausreichend eingedeckt? Wunderbar.\n\nGefreiter Cole und Rüstmeisterin Richter haben noch diese Tasche in den Ruinen in der Nähe gefunden. Sie dachten, Ihr hättet vielleicht Verwendung dafür.", sourceObjectiveStatus = "unverified-source-field" }
quests[55195] = { id = 55195, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nachhall", description = "Hatis Geist ist ewig an den Euren gebunden, <Jäger/Jägerin>. Aber er trägt jetzt auch eine Verbindung zum Tempel der Stürme in sich. Und auch zu Silithus, befürchte ich.\n\nDer Donnerfunke teilt diese Bande. Indem Ihr ihn hier verankert, könnt Ihr die verschiedenen Aspekte von Hati anrufen und sie auch an Euch binden.\n\nKeine Sorge, Skoll und ich werden den Donnerfunken mit unserem Leben beschützen! Er wird sicher sein.", sourceObjective = "Verwendet den Donnerfunken, um eine Essenz von Hati zu beschwören.", completion = "Ihr könnt wiederkommen, wann immer Ihr Euch nach Hatis Nähe sehnt.\n\nIhr werdet auf ewig an meinem Hof willkommen sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[55196] = { id = 55196, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Harpyienproblem", description = "Wir müssen die verbleibenden Überlebenden meiner Expedition finden, bevor die Oger sie in ihren dunklen Ritualen opfern!\n\nIch habe gesehen, dass einer der Überlebenden von Harpyien verschleppt wurde. Sie haben ein Nest nördlich von hier.\n\nKee-La und ich werden Euch dort mit einem Späherbericht treffen.", sourceObjective = "Trefft Euch mit Henry Garrick in der Nähe des Harpyiennests.", completion = "Die Harpyien scheinen finstere Pläne zu schmieden. Wir brauchen Eure Hilfe in dieser Sache.", sourceObjectiveStatus = "unverified-source-field" }
quests[55210] = { id = 55210, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Batterien nicht im Lieferumfang enthalten", sourceObjective = "Sammelt 10 beschädigte Energiezellen.", progress = "Aus alt mach neu! Das ist doch kein Problem.", completion = "Die sind zwar beschädigt... aber nicht ZU beschädigt... Ja, ich glaube, die bringe ich wieder zum Laufen.\n\nIhr dürft eine als Entschädigung behalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[55211] = { id = 55211, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Neuer Saft für den Rostbolzen", description = "Unser persönlicher Generator ist wertlos, bis wir seine leeren Energiezellen wieder aufladen.\n\nWie mein lieber Bruder immer sagt: Energiezellen sind das Lebenselixier der Innovation. Alles hier in Mechagon benötigt Strom und die Energiezellen liefern den Strom in einem wundervoll universellen Format.\n\nWenn sie allerdings leer sind, werfen die Leute sie einfach achtlos weg.\n\nDie meisten Leute sind eben töricht, liebes Versuchsobjekt.\n\nWir haben die Technologie perfektioniert, mit der man eine Handvoll Energiezellen wieder vollständig aufladen kann.\n\nWerdet Ihr uns dabei helfen, sie zu testen?", sourceObjective = "Benutzt den NRG-100, um 6 Generatorenergiezellen aufzuladen.", completion = "Wundervolle Arbeit, mein liebes Versuchsobjekt!\n\nIch hatte ungewöhnliche elektrische Entladungen beim NRG-100 bemerkt, aber ich verstehe jetzt, dass meine Sorge unberechtigt war.\n\nEr ist immer noch in einem Stück. So wie Ihr!\n\nNun schaut nicht so. Ihr habt bereits länger überlebt als fünf Prozent unserer Versuchsobjekte!", sourceObjectiveStatus = "unverified-source-field" }
quests[55213] = { id = 55213, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Energiezellen für alle", description = "Man munkelt in der Stadt, dass die Aufladestation in Bondos Hof heute repariert werden soll!\n\nDiese Aufladestation ist die beste Möglichkeit, um all die leeren Energiezellen aufzuladen, die sich in Eurer Tasche angesammelt haben. Oder in den Taschen anderer Leute. Oder im mechanischen Inneren der Roboter, die Euch nicht gehören, die Ihr aber rechtmäßig zerstören dürft.\n\nWenn Ihr Euch leere Energiezellen besorgt habt, helft beim Bau der Aufladestation in Bondos Hof und ladet dort all Eure leeren Energiezellen auf!", sourceObjective = "Findet 5 leere Energiezellen in Mechagon.\n\nHelft danach beim Bau der Aufladestation und benutzt sie, um Eure leeren Energiezellen aufzuladen.", completion = "Wundersam! Ich hoffe die lästigen Troggs haben Euch in Ruhe aufladen lassen.\n\nSie verstehen Technologie einfach überhaupt nicht. Ich schäme mich ehrlich gesagt für sie.", sourceObjectiveStatus = "unverified-source-field" }
quests[55214] = { id = 55214, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reißende Naht", description = "Ich... ich brauche einen Augenblick, {name}.\n\n<Delormi wirkt desorientiert und stützt sich an Eurer Schulter. Sie hält ihre Hand an ihre Stirn und bleibt für einen Moment so stehen.\n\nSchließlich kommt sie wieder zu Kräften, reckt sich auf und wendet sich Euch zu.>\n\nIch kann mich an gewisse Dinge nicht mehr erinnern. Wichtige Dinge, die jetzt verloren sind. Wir müssen sie aufhalten, {name}, koste es, was es wolle.", sourceObjective = "Folgt Delormi durch den Zeitriss.", progress = "Ich fühle mich so schwach...", completion = "Dieser Riss dort, schließt ihn nicht! Das ist der, den wir suchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[55215] = { id = 55215, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Kreislauf des Lebens" }
quests[55216] = { id = 55216, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Probe", description = "Xanjo sprach in den höchsten Tönen von Eurem Können. Aber ich muss mir selbst eine Meinung bilden. Ich möchte Euch nicht beleidigen, aber das ist zu Eurem und meinem Besten. Denn solltet Ihr der Aufgabe nicht gewachsen sein, könnte es Euch das Leben kosten.\n\nWenn Ihr einverstanden seid, würde ich Euch gerne einem Test unterziehen, um zu sehen, wie gut Ihr Euch in der Lederverarbeitung versteht.\n\nBringt mir drei Trommeln des Mahlstroms, die Ihr selbst hergestellt habt, um Euer Können und die Beständigkeit Eurer Arbeit zu beweisen.\n\nWenn das Ergebnis meine Erwartungen erfüllt, werde ich Euch in meine Pläne einweihen.", sourceObjective = "Stellt 3 Trommeln des Mahlstroms her und bringt sie zu Atikka Mondjäger.", progress = "<Erleichtert über Eure Rückkehr atmet Atikka hörbar auf.>\n\nHabt Ihr die Trommeln?", completion = "Enge Nähte. Gleichmäßige Spannung. Keine Risse oder Löcher.\n\nIhr werdet Euch gut machen.\n\n<Atikka lehnt sich näher und flüstert Euch zu.>\n\nMein Plan ist es, Trommeln aus seltenen und mächtigen Materialien herzustellen. Durch die spezielle Bauweise der Trommeln lässt sich die rohe und ursprüngliche Macht der getöteten Bestien anzapfen. So können wir diesen Allianzhunden eine Lektion erteilen, die sie so bald nicht vergessen werden.\n\nFür die Trommeln brauchen wir außerdem einen besonderen Schlägel. Aber macht Euch keine Sorgen, sobald unsere Arbeit getan ist, werde ich Euch beibringen, wie Ihr solch einen Schlägel herstellen könnt.", sourceObjectiveStatus = "unverified-source-field" }
quests[55217] = { id = 55217, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Lebensschuld begleichen", description = "Als ich hörte, dass die Allianz Dazar'alor angegriffen hat, musste ich daran denken, wer alles bei ihrem Angriff auf Camp Taurajo gestorben ist. Ich kann nicht länger untätig dabei zusehen, wie sie uns weiter abschlachten!\n\nIhr müsst nach Donnerfels reisen und Sheza Wildmähne auf der Anhöhe der Ältesten aufsuchen. Fragt sie nach ein paar Stücken aus ihrer privaten Sammlung.\n\nIch werde nicht in die Details gehen, aber sie verdankt mir ihr Leben. Und sie zu treffen... würde zu viele schmerzhafte Erinnerungen wachrufen... in uns beiden.\n\nSucht sie auf. Sagt ihr, dass ich Euch geschickt habe und dass wir hiermit quitt sind.", sourceObjective = "Sprecht mit Sheza Wildmähne in Donnerfels.", completion = "<Ihr erklärt Eure Mission und Eure Verbindung zu Atikka.>\n\nIch verstehe. Natürlich bin ich mehr als nur gewillt, Euch zu helfen, besonders weil Atikka fragt.\n\nAllerdings werdet Ihr mithelfen müssen, wenn es Euch recht ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[55218] = { id = 55218, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shezas wertvolles Leder", description = "Ich habe einen Vorrat an äußerst seltenen Ledern oder eher gesagt... ich hatte einmal einen Vorrat.\n\nIch weiß nicht wie, aber die Venture Co. muss mitbekommen haben, wie wertvoll meine Sammlung ist, denn sie haben sie mitgehen lassen!\n\nUnd sie waren auch noch so frech und haben eine Nachricht hinterlassen, in der sie mir das Angebot machen, sie für 1000 Gold wieder zurückzukaufen! Als \"ehemaliger Besitzer\" wüsste ich ja \"nur zu gut um den Wert ihrer neuesten Akquisition.\"\n\nDie Nachricht besagt, dass sie so lange auf den Felsen im Osten warten, bis sich ein Käufer findet.\n\nWenn Ihr ihnen die Häute irgendwie abnehmen könnt, gehören sie Euch.", sourceObjective = "Holt Euch die seltenen Bälge zurück.", progress = "Wie war sie?", completion = "<Ihr erzählt, was in Mulgore vorgefallen ist.>\n\nBah! Diese elenden Goblins und ihre Gier nach Gold!\n\n<Attika holt tief Luft, um sich wieder zu beruhigen.>\n\nTut mir leid, dass Ihr das mit ansehen musstet. Es missfällt mir zutiefst, dass unser Kampf uns nur deswegen schwerer fällt, weil diese grünhäutigen Winzlinge meinen, sich auch das letzte bisschen Kupfer unter den Nagel reißen zu müssen.", sourceObjectiveStatus = "unverified-source-field" }
quests[55219] = { id = 55219, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dubben in Donnertotem", description = "Als die Legion angriff, habe ich mich mit einem Mitglied der Hochbergtauren getroffen. Er ist ein Meister in der Herstellung und dem Spielen von Trommeln.\n\nTorv bleibt normalerweise für sich, aber er ist genau so brillant wie verrückt.\n\nWenn es jemanden gibt, der weiß, wo wir die Rohmaterialien für etwas dieser Größenordnung herbekommen können, dann ist er es.\n\nBegebt Euch nach Donnertotem und fragt Torv Dubstampf, ob er weiß, wo wir adäquate Schuppen finden können. Das Tier sollte möglichst noch leben, damit die Macht in den Schuppen frisch bleibt.", sourceObjective = "Sprecht mit Torv Dubstampf in Donnertotem.", completion = "Atikka schickt Euch? Ha! Wie geht's dem alten Rindvieh?!\n\nHmm, Schuppen sagt Ihr.\n\n<Seine Augen schnellen hin und her, als er seinen Blick in die Ferne schweifen lässt. Sein grimmiger Ausdruck verwandelt sich plötzlich in einen Ausdruck des Vergnügens.>\n\nIch habe genau das Richtige für Euch!", sourceObjectiveStatus = "unverified-source-field" }
quests[55220] = { id = 55220, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlagen, bis die Schuppen fliegen", description = "Habt Ihr schon mal davon gehört, dass kleine goldene Karpfen als Haustiere gehalten werden?\n\nNun, sie werden in Teichen ohne natürliche Fressfeinde gehalten und mit der Zeit können sie enorme Ausmaße erreichen, je nach Futterangebot.\n\nVor Jahrhunderten lebte einer dieser Fische in dem Teich hoch oben auf einem Berg. Er fraß einfach alles auf, bis er schließlich anfing zu hungern.\n\nAlso hob mein Volk einen kleinen Fluss aus, der den Teich mit dem Meer verband und dem Fisch letztlich zur Freiheit verhalf.\n\nHeute erzählen sich die Fischer von einem gigantischen goldenen Fisch, der nahe der Freifallklippe auf sie lauert und angreift.\n\nTötet ihn und bringt seine Schuppen zurück zu Atikka.", sourceObjective = "Sammelt glänzende goldene Schuppen.", progress = "Habt Ihr Euch schon mit Torv getroffen?", completion = "<Nachdem er Eurer Nacherzählung von Torvs Plan zugehört hat, bricht Attika in schallendes Gelächter aus.>\n\nEin Jahrhunderte alter Goldfisch?!\n\nIch habe Euch doch gesagt, dass er nicht mehr Alle beisammen hat!\n\nAhhh, gute Arbeit. Ich kann von Glück reden, dass Euch der Guppy nicht erwischt hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[55221] = { id = 55221, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Knochenarbeit", description = "Als ich hierher unterwegs war, bemerkte ich vom Meer aus die Überreste eines unglaublich riesigen Ungeheuers auf der nahe gelegenen Halbinsel.\n\nWas auch immer es war, es muss sehr mächtig gewesen sein. Daher glaube ich, dass es eine ideale Quelle für die Knochenelemente der Trommeln sein könnte.\n\nGeht zur Halbinsel, ich meine, sie wird \"Xibala\" genannt, und füllt eine Tasche mit den Knochen, die Ihr dort findet.\n\nWenn Euch dabei diese verdammten Allianzler in die Quere kommen, zeigt ihnen keine Gnade. Das haben sie sich selbst zuzuschreiben.", sourceObjective = "Sammelt 18 beständige Knochen.", progress = "Konntet Ihr die Knochen bekommen?\n\nHat Euch die Allianz Probleme bereitet?", completion = "Ah, die sehen gut aus.\n\nUnd noch froher macht mich die Nachricht, dass die Allianz auch hinter ihnen her war und Ihr sie ihnen vor der Nase weggeschnappt habt! Hehehe!", sourceObjectiveStatus = "unverified-source-field" }
quests[55222] = { id = 55222, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlagende Instrumente", description = "Wir haben alles zusammen, was wir für die Herstellung der Trommel brauchen, alles außer dem Segen der Erdenmutter.\n\nDie Trommel ist nur ein Gefäß, genauso wie ein Becher. Wir müssen die Trommel mit Macht füllen, genauso wie wir einen Becher füllen müssen, um daraus zu trinken.\n\nEs wird nicht einfach werden, sie davon zu überzeugen, uns dabei zu helfen, ein Werkzeug des Krieges zu erschaffen, aber ich werde sie beschwören, dass sie damit ihre Kinder beschützt.\n\nWährend ich mich darum kümmere, müsst Ihr die Trommel selbst herstellen.\n\nSie sollte allerdings nicht zu groß ausfallen. Denn je größer der Trommelkörper, desto mehr Macht enthält sie zwar, aber desto schwerer wird es, sie zu tragen.", sourceObjective = "Stellt 6 Trommeln der Urmacht her.", progress = "<Attika ist sichtlich erschöpft, aber er versucht, es sich nicht anmerken zu lassen.>", completion = "<Atikka prustet erleichtert, bevor er Euch sein Gesicht zuwendet und Euch ein schwaches Lächeln schenkt.>\n\nWir haben es geschafft, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[55223] = { id = 55223, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Instrumente der Zerstörung", description = "Wir sind fast fertig.\n\nObwohl die Trommeln mächtig sind, sind sie hier im Hafen vollkommen nutzlos.\n\nWenn wir den größten Nutzen aus ihnen ziehen wollen, müssen wir sie über die Inseln verteilen. Ich schlage vor, dass wir sie in jedem Gebiet hier und in Kul Tiras platzieren, damit sie Euch jeweils dort Hilfe leisten können, wenn Ihr auf einer Mission unterwegs seid oder Euch hinter feindlichen Linien befindet.\n\nSucht Euch in jedem Gebiet möglichst zentrale Standorte für die Trommeln aus.\n\nBei Eurer Rückkehr werde ich Euch zeigen, wie Ihr den Schlägel herstellt, mit dem Ihr auf den Trommeln spielen könnt.", sourceObjective = "Platziert die Trommeln der Urmacht an verschiedenen Orten in Zandalar und Kul Tiras.", completion = "Ich bin froh, Euch in einem Stück wiederzusehen.\n\nRückblickend betrachtet wäre es besser gewesen, wenn ich Euch vorher gezeigt hätte, wie man den Schlägel macht. Aber wie es aussieht, ist alles gutgegangen.\n\nNa schön, dann werde ich Euch jetzt einmal zeigen, wie man den Schlägel der donnernden Häute herstellt...", sourceObjectiveStatus = "unverified-source-field" }
quests[55224] = { id = 55224, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rank 2 - Poen test", description = "Sammelt Beutel mit verderbter Tinte von den nazothianischen Hirnkalmaren.\n\nDie Naga nutzen sie, um uns zu kontrollieren. Schauen wir mal, ob es auch andersherum funktioniert.Ihr erlernt:" }
quests[55225] = { id = 55225, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Supersäfte" }
quests[55226] = { id = 55226, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jagt den Feind" }
quests[55227] = { id = 55227, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Äonenhandwerkerin", description = "Guten Tag!\n\nEine Nachtelfe kam hier vorbei und wollte wissen, wer der beste Lederverarbeiter ist, den ich kenne und ob derjenige ein Problem damit hat, sich die Hände schmutzig zu machen.\n\nIch erwähnte Euch und sie bat mich, Euch auszurichten, sie im Hafen von Boralus zu treffen.\n\nSie sagte nicht, wofür sie <meinen besten Schüler/meine beste Schülerin> braucht, aber sie verhielt sich, als ginge es um etwas Großes.\n\nSucht unten an den Docks nach ihr. Sie hat weißes Haar, violette Tätowierungen und einen Schildkrötengefährten namens \"Rille\". Zeigt ihr, was ich Euch gelehrt habe!", sourceObjective = "Trefft die nachtelfische Lederverarbeiterin im Hafen von Boralus.", completion = "Der Göttin sei Dank!\n\nWir haben viel zu besprechen.", sourceObjectiveStatus = "unverified-source-field" }
quests[55228] = { id = 55228, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Probe", description = "Kassandra lobt Eure Fähigkeiten über alle Maßen, aber ich muss mich selbst von ihnen überzeugen. Seid nicht gekränkt, das ist sowohl zu Eurem als auch unserem eigenen Besten, da die bevorstehende Aufgabe Euch das Leben kosten könnte, wenn Ihr nicht bereit seid.\n\nWenn Ihr einwilligt, möchte ich Euch bitten, Euch einem Test zu unterziehen, um Euer Geschick als <Lederverarbeiter/Lederverarbeiterin> unter Beweis zu stellen.\n\nBringt mir drei Trommeln des Mahlstroms, die Ihr selbst hergestellt habt. Das wird Eure Fähigkeiten und die Beständigkeit Eurer Arbeit belegen.\n\nWenn das Ergebnis den Ansprüchen entspricht, werde ich Euch in meinen Plan einweihen.", sourceObjective = "Stellt 3 Trommeln des Mahlstroms her und bringt sie zu Daniss Geisttänzer.", progress = "Habt Ihr die Trommeln?", completion = "Saubere Nähte. Gleichmäßige Spannung. Keine Risse oder Löcher.\n\nHervorragend.\n\nMein Plan ist es, Trommeln aus seltenen und mächtigen Materialien zu fertigen, mit denen man die rohe Urmacht der getöteten Bestien bändigen kann.\n\nMit dieser Macht werdet Ihr die Horde lehren, dass \"Zuhause\" kein Ort ist, den man verbrennen kann, dass Hoffnung nicht getötet werden kann und dass wir stärker sind als Flammen.\n\nMan benötigt einen speziellen Schlägel, um die Trommeln zu benutzen. Wenn Eure Arbeit getan ist, werde ich Euch lehren, wie man den Schlägel anfertigt.", sourceObjectiveStatus = "unverified-source-field" }
quests[55229] = { id = 55229, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schulden begleichen", description = "Ich war auf Teldrassil, als der Baum in Brand gesetzt wurde. Trotz der Panik und des Chaos wusste ich, dass ich keine Ruhe finden werde, solange die Täter ungestraft bleiben.\n\nReist für mich nach Sturmwind, sucht Telonis nahe der Löwenruh auf und bittet ihn um einen Teil seiner privaten Sammlung.\n\nIch habe ihn aus den Flammen gerettet, also schuldet er mir so einiges. Ich würde selbst gehen, aber der Verlust von Teldrassil ist noch immer eine offene Wunde. Sie braucht Zeit, um zu heilen.\n\nFindet ihn, sagt ihm, ich habe Euch geschickt und dass dieser Gefallen seine Schuld begleichen wird.", sourceObjective = "Sprecht mit Telonis in Sturmwind.", completion = "<Ihr erklärt Eure Mission und Eure Verbindung zu Daniss.>\n\nIch verstehe. Natürlich bin ich mehr als gewillt, Euch zu helfen. Sie mag zwar eine T'lara sein, aber ich verdanke ihr mein Leben.\n\nLeider gibt es da ein kleines Problem, das erst aus der Welt geschafft werden müsste.", sourceObjectiveStatus = "unverified-source-field" }
quests[55230] = { id = 55230, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Telonis' wertvolles Leder", description = "Ich habe einen Vorrat an äußerst seltenen Ledern oder eher gesagt... ich hatte einmal einen Vorrat.\n\nEine Diebesbande muss mitbekommen haben, wie wertvoll meine Sammlung ist, denn sie haben sie mir gestohlen!\n\nUnd dann waren sie auch noch so dreist und haben eine Nachricht hinterlassen, in der sie mir das Angebot machen, sie wieder zurückzukaufen! Als \"ehemaliger Besitzer\" wüsste ich ja \"nur zu gut um den Wert ihrer neuesten Akquisition.\"\n\nDie Nachricht besagt, dass sie im Osten im Vorgebirge hinter dem Schloss warten, bis sie einen anderen Käufer finden.\n\nWenn Ihr ihnen die Häute irgendwie abnehmen könnt, gehören sie Euch.", sourceObjective = "Holt Euch die seltenen Bälge zurück.", progress = "Wie kommt er zurecht?", completion = "<Ihr erzählt, was in Sturmwind vorgefallen ist.>\n\nTypisch Menschen. Verbündete auspressen, weil nur ihr eigenes Leiden für sie zählt!\n\n<Daniss holt tief Luft, um sich wieder zu beruhigen.>\n\nTut mir leid, {name}. Aus mir spricht lediglich die Frustration.\n\nIch kenne den Krieg gut, aber Sylvanas' Taktiken machen diesen besonders unerträglich. Ich wollte nicht ihre... Vorgehensweise in Frage stellen. Ich wünschte nur, wir hätten solche Mittel nicht nötig.\n\nNun gilt es, unseren Glauben an die Allianz zu bewahren.", sourceObjectiveStatus = "unverified-source-field" }
quests[55231] = { id = 55231, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Noch ein Geisttänzer", description = "Als die Legion angriff, reiste mein Partner nach Val'sharah, um den Dämonen Widerstand zu leisten.\n\nMevris mag eiskalt und dickköpfig sein, aber er ist zielstrebig und bereit, für diese Ziele Opfer zu bringen. Das ist einer der Gründe, warum ich mich in ihn verliebt habe.\n\nWenn jemand weiß, wo wir die Materialien für etwas dieses Ausmaßes herbekommen, ist er das.\n\nReist nach Val'sharah und sucht im Tempel von Elune nach ihm. Erzählt ihm von unserem Plan und dass wir seine Hilfe brauchen, um Schuppen zu beschaffen.", sourceObjective = "Sprecht mit Mevris Geisttänzer in Val'sharah.", completion = "Daniss schickt Euch? Ist alles in Ordnung?\n\n<Ihr erklärt ihm den Plan und dass Ihr Schuppen benötigt.>\n\nHmmm, Schuppen sagt Ihr.", sourceObjectiveStatus = "unverified-source-field" }
quests[55232] = { id = 55232, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mevris' Monster", description = "Es gibt eine Hydra, die uns in letzter Zeit ein Dorn im Auge ist. Sie lebt draußen beim Dämmernden Riff, fast genau westlich von hier.\n\nSie greift vorbeifahrende Schiffe an, wodurch es schwer ist, Vorräte nach und aus Bradenbach zu transportieren.\n\nIch habe Leute geschickt, um sich darum zu kümmern, aber sie sind noch nicht zurück.\n\nGeht. Tötet die Hydra und bringt Daniss ihre Schuppen.\n\nUnd wenn Ihr sie seht, sagt ihr von mir...\n\n<Mevris hält inne und wägt seine Worte und deren Bedeutung ab.>\n\nNichts.", sourceObjective = "Sammelt glänzende azurblaue Schuppen.", progress = "Habt Ihr Euch schon mit Mevris getroffen?", completion = "<Nachdem sie Eure Nacherzählung von Mevris' Plan gehört hat, nickt Daniss nachdenklich.>\n\nIch bin froh, dass Ihr ihm helfen konntet. Er ist nun schon eine ganze Weile fort. Hoffentlich existiert mit dem Ableben dieser Kreatur ein Hindernis weniger, das ihn von der Rückkehr nach Hause abhält.\n\nAch, und mit den Schuppen, das war gute Arbeit. Sie scheinen für ihre Aufgabe perfekt geeignet zu sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[55233] = { id = 55233, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Knochenarbeit", description = "Als ich in den Tiragardesund gesegelt bin, hörte ich einige Seefahrer über die Hordepräsenz hier reden.\n\nScheinbar nehmen sie den Kadaver einer riesigen Kreatur auseinander, die dort an Land gespült wurde.\n\nWas auch immer das war – wenn die Horde es will, müssen wir sicherstellen, dass sie es nicht bekommt.\n\nFindet die Horde, lasst sie nichts mitnehmen und stellt fest, ob wir irgendwelche Knochen der Kreatur für unsere Trommeln verwenden können.\n\nZeigt ihnen keine Gnade, {name}.", sourceObjective = "Sammelt 18 beständige Knochen.", progress = "Habt Ihr Euch schon um unser gemeinsames Problem gekümmert?", completion = "Diese Knochen sehen gut aus.\n\nEs freut mich zu hören, dass die Horde umsonst einen Blutpreis gezollt hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[55234] = { id = 55234, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlagende Instrumente", description = "Wir haben alles zusammen, was wir für die Herstellung der Trommel brauchen, alles außer Elunes Segen.\n\nDie Trommel ist nur ein Gefäß, genauso wie ein Becher. Wir müssen die Trommel mit Macht füllen, genauso wie wir einen Becher füllen müssen, um daraus zu trinken.\n\nJetzt, wo Tyrande den Mantel der Nachtkriegerin trägt, ist der größte Teil von Elunes Kraft in Anspruch genommen. Einen weiteren Gefallen zu erbitten, ist nicht unwesentlich, aber ich muss es versuchen.\n\nWährenddessen möchte ich, dass Ihr die Trommel herstellt. Versucht sie klein zu halten. Denn je größer der Trommelkörper, desto mehr Macht enthält sie zwar, aber desto schwerer wird es, sie zu tragen.", sourceObjective = "Stellt 6 Trommeln der Urmacht her.", progress = "<Daniss ist sichtlich erschöpft, aber sie versucht, es sich nicht anmerken zu lassen.>", completion = "<Daniss atmet erleichtert aus, bevor sie sich Euch zuwendet und Euch ein schwaches Lächeln schenkt.>\n\nWir haben es geschafft, {name}.\n\nEinst nannten sie mich \"T'lara\", eine Kriegerin, die nur mit Worten kämpft. Doch diese Worte haben uns die Stärke einer Göttin verliehen.\n\nMit diesen Trommeln werden wir die Horde in die Knie zwingen.", sourceObjectiveStatus = "unverified-source-field" }
quests[55235] = { id = 55235, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Instrumente der Zerstörung", description = "Eine Sache bleibt noch zu tun.\n\nObwohl die Trommeln mächtig sind, sind sie hier in der Stadt vollkommen nutzlos.\n\nWenn wir den größten Nutzen aus ihnen ziehen wollen, müssen wir sie verteilen. Ich schlage vor, dass wir sie in jedem Gebiet hier und in Zandalar platzieren, damit sie Euch jeweils dort Hilfe leisten können, wenn Ihr auf einer Mission unterwegs seid oder Euch hinter feindlichen Linien befindet.\n\nSucht Euch in jedem Gebiet möglichst zentrale Standorte für die Trommeln aus.\n\nBei Eurer Rückkehr werde ich Euch zeigen, wie Ihr den Schlägel herstellt, mit dem Ihr auf den Trommeln spielen könnt.", sourceObjective = "Platziert die Trommeln der Urmacht an verschiedenen Orten in Zandalar und Kul Tiras.", completion = "Ihr seid zurück! Ich nehme an, es ist alles gut verlaufen?\n\nRückblickend betrachtet wäre es besser gewesen, wenn ich Euch vorher gezeigt hätte, wie man den Schlägel macht. Aber wie es aussieht, ist alles gutgegangen.\n\nNa schön, dann werde ich Euch jetzt einmal zeigen, wie man den Schlägel der donnernden Häute herstellt...", sourceObjectiveStatus = "unverified-source-field" }
quests[55242] = { id = 55242, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hilfe für einen Goblin" }
quests[55243] = { id = 55243, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Tochter von Torcali", description = "Man sagt schon lang, dass 'n Terrorhorn das tapferste Tier im Dschungel is'. Deshalb sin' sie die Reittiere unserer Krieger.\n\nDiesmal könnte diese Tapferkeit nich' von Vorteil sein. Die Kleine is' weggerannt und ich glaub nich', dass sie einfach nur Hunger hatte.\n\nEs wär am besten, sie zu find'n, bevor ihr was passiert.", sourceObjective = "Findet den Spross von Torcali in den Wilden Landen und bewahrt ihn vor Gefahren.", completion = "<Der Spross von Torcali steht hoch erhobenen Hauptes da.>", sourceObjectiveStatus = "unverified-source-field" }
quests[55244] = { id = 55244, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abseits der Herde", description = "<Der Spross von Torcali starrt sehnsüchtig aus dem Pferch. Sein Blick scheint den anderen Terrorhörnern in der Nähe zu folgen.\n\nSie könnte vielleicht eine Ablenkung vertragen.>", sourceObjective = "Spielt mit Eurem Terrorhorn.", completion = "<Der Spross von Torcali stupst liebevoll mit ihrem Kopf Euer Bein an.>", sourceObjectiveStatus = "unverified-source-field" }
quests[55245] = { id = 55245, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Essen wie ein Terrorhorn", description = "<Der Spross von Torcali sucht Eure Hand nach Futterresten ab und gibt ein leises, enttäuschtes Geräusch von sich.>", sourceObjective = "Füttert den Spross von Torcali.", progress = "<Der Spross von Torcali zappelt ungeduldig herum.>", completion = "<Der Spross von Torcali blinzelt vertrauensvoll zu Euch hinauf und macht ein warmes, grummelndes Geräusch.>", sourceObjectiveStatus = "unverified-source-field" }
quests[55246] = { id = 55246, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Noch grünere Weidegründe", description = "Seit Torcali die Kleine gesegnet hat, wächst sie wie Unkraut. Dadurch is' sie ständig hungrig.\n\nSie is' wieder ausgebüxt, weil sie noch mehr Futter sucht. Bevor Ihr fragt, es is' nich' meine Aufgabe, sie davon abzuhalt'n, das zu tun, was immer sie will. Ich muss nur darauf acht'n, dass sie sicher is'.\n\nWahrscheinlich geht's ihr gut. Bringt sie nach Hause, und wenn sie zickig is', könnt Ihr es mit Bestechung versuch'n.", sourceObjective = "Findet den Spross von Torcali und bringt ihn in seinen Pferch zurück.", completion = "<Der Spross von Torcali wirkt sehr selbstzufrieden.>", sourceObjectiveStatus = "unverified-source-field" }
quests[55247] = { id = 55247, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verdientes Vertrauen", description = "Ich glaub, mein Loa is' meiner Meinung, wenn ich sag, dass Ihr Euch ihrer Begleitung würdig erwies'n habt.\n\nSie is' jetzt groß genug, dass sie Euch überall hintragen kann, wohin Ihr wollt.\n\nIch hab Euch vom Abrichter einen Sattel mach'n lass'n. Geht, holt ihn ab und ich helf Euch dabei, ihn auf den Rücken Eures neuen Reittiers zu leg'n.\n\nGlückwunsch, {name}.", sourceObjective = "Holt den Terrorhornsattel im Kriegsbestienkral ab.", progress = "<Li'zal reibt sich den Kopf und stöhnt.>", completion = "Ich konnte sie nich' aufhalt'n. Sie hat das Tor gerammt...\n\nAls ob sie besess'n wäre...", sourceObjectiveStatus = "unverified-source-field" }
quests[55248] = { id = 55248, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grünere Weidegründe", description = "Ihr habt die Kleine ausreichend gefüttert, aber manchmal woll'n sie was andres.\n\nIch hab nich' geseh'n, wo das Junge hingerannt is', aber Ihr solltet dort suchen, wo das Gras richtig grün is'. Wahrscheinlich erwischt ihr sie dabei, es zu fress'n.\n\nSollte sie zickig sein, wenn Ihr sie nach Hause bringen wollt, versucht es mit Bestechung.", sourceObjective = "Findet den Spross von Torcali und bringt ihn in seinen Pferch zurück.", completion = "<Der Spross von Torcali wirkt sehr selbstzufrieden.>", sourceObjectiveStatus = "unverified-source-field" }
quests[55249] = { id = 55249, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abseits der Herde", description = "<Der Spross von Torcali starrt sehnsüchtig aus ihrem Gehege. Ihr Blick scheint den anderen Terrorhörnern in der Nähe zu folgen.\n\nVielleicht könnte sie eine kleine Ablenkung brauchen.>", sourceObjective = "Muntert Euer Terrorhorn auf.", completion = "<Der Spross von Torcali stupst liebevoll mit ihrem Kopf Euer Bein an.>", sourceObjectiveStatus = "unverified-source-field" }
quests[55250] = { id = 55250, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wachsender Appetit", description = "<Der Spross von Torcali sucht Eure Hand nach Futter ab und macht kurz ein enttäuschtes Geräusch.>", sourceObjective = "Füttert den Spross von Torcali.", completion = "<Der Spross von Torcali blinzelt vertrauensvoll zu Euch hinauf und macht ein warmes, grummelndes Geräusch.>", sourceObjectiveStatus = "unverified-source-field" }
quests[55251] = { id = 55251, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Tochter von Torcali", description = "Man sagt schon lang, dass 'n Terrorhorn das tapferste Tier im Dschungel is'. Deshalb sin' sie die Reittiere unserer Krieger.\n\nDiesmal könnte diese Tapferkeit nich' von Vorteil sein. Die Kleine is' weggerannt und ich glaub nich', dass sie einfach nur Hunger hatte.\n\nEs wär am besten, sie zu find'n, bevor ihr was passiert.", sourceObjective = "Findet den Spross von Torcali im Tümpel und bewahrt ihn vor Gefahren.", completion = "<Der Spross von Torcali steht hoch erhobenen Hauptes da.>", sourceObjectiveStatus = "unverified-source-field" }
quests[55252] = { id = 55252, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Loa ohne Tempel", description = "Ich hab mir 'n paar Gedanken über Eure Situation gemacht, {name}.\n\nIs nich' Eure Schuld, dass der Goblin uns gelinkt hat. Ich bin auch auf seinen Plan reingefall'n. Von heute an verzeih ich Euch.\n\nAber das hilft dem Sprössling nich'. Ich fürchte, wir könnt'n sie verlier'n, wenn wir nicht handeln. Wir müss'n zum Loa der Reisenden fleh'n, dem wandernden Berg, dem groß'n Bollwerk, der Großmutter der Terrorhörner, um ihr Kind zu rett'n.\n\nBringt diese Opfergabe zu ihrem Schrein und fleht um ihren Seg'n... und ihre Vergebung.", sourceObjective = "Bringt L'kalas Opfergabe zu Torcali.", progress = "<Das große Terrorhorn sieht auf Euch herab.>", completion = "<Eine warme, aber donnernde Stimme erschallt in Eurem Verstand.>\n\nIhr seid gekommen, um Eure Schuld zu tilgen. Gut. Beginnen wir.", sourceObjectiveStatus = "unverified-source-field" }
quests[55253] = { id = 55253, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Demonstration des Glaubens", description = "<Torcalis Stimme erklingt in Eurem Verstand.>\n\nIch habe Eure Taten aus der Ferne beobachtet, kleines Wesen. Ihr habt Fehler gemacht und eines meiner Jungen musste dafür leiden.\n\nIch vergesse nicht, aber ich kann vergeben.\n\n<Das riesige Terrorhorn berührt das Bündel mit Opfergaben mit der Nase.>\n\nWie mein Volk an mich glaubt, so glaube ich an Euch. Bringt meinen Segen zu meinem Kind und sie wird erwachen.", sourceObjective = "Bringt die gesegnete Opfergabe zu Eurem Terrorhornjungtier im Kriegsbestienkral.", completion = "<Der Spross von Torcali späht verschlafen zu Euch auf und grummelt zufrieden.>", sourceObjectiveStatus = "unverified-source-field" }
quests[55254] = { id = 55254, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein nie endender Schlaf", description = "<Das Terrorhornjungtier schläft trotz all Eurer Versuche, es zu wecken, weiter tief und fest.\n\nSo lange sollte es vermutlich nicht schlafen. Ihr solltet mit Abrichterin L'kala sprechen.>", sourceObjective = "Sprecht mit Abrichterin L'kala im Kriegsbestienkral.", completion = "Wie ich seh', habt Ihr den Zustand Eures Jungtiers bemerkt.\n\nNachdem es Eure Verantwortung is', werd ich akzeptier'n, dass Ihr nicht gewusst habt, was Ihr tut, als wir das hier begonn' haben.\n\nIch hoff, Ihr seid bereit, das zu ändern.", sourceObjectiveStatus = "unverified-source-field" }
quests[55258] = { id = 55258, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlafen, essen, schlafen, essen...", description = "<Der Spross von Torcali stößt den Sack mit Kräutern mit ihrer Schnauze umher.\n\nDann sieht sie Euch an und stampft ungeduldig auf der Stelle.>", sourceObjective = "Füttert den Spross von Torcali.", progress = "<Der Spross von Torcali drückt ihre Schnauze in Eure Hand, um nach Futter zu suchen.>", completion = "<Der Spross von Torcali trompetet voll Zufriedenheit.>", sourceObjectiveStatus = "unverified-source-field" }
quests[55264] = { id = 55264, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kalligraphie" }
quests[55298] = { id = 55298, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nach dem Riesen angeln", description = "In diesen Gewässern lauert ein riesiger Fisch, und er hat schon einige große Probleme gemacht! \n\nEr frisst andere Fische, Fischer und jede Menge teure Ausrüstung. Ich habe erst gestern mit eigenen Augen gesehen, wie er eine wunderschöne Zigby-300-Angelrute mitsamt Eigentümer verschlungen hat!\n\nIch habe einen Plan, aber ich habe fast meine gesamte Ausrüstung im Gewässer hier verloren. Könnt Ihr mir dabei helfen, mein Zeug wieder zu angeln?", sourceObjective = "Findet den anodisierten Wachfisch, eine Rundmaulgrundel und das Saugrohr.", progress = "Habt Ihr die Sachen besorgt?", completion = "Gute Arbeit, {name}. Jetzt kann ich den Fischsauger bauen!", sourceObjectiveStatus = "unverified-source-field" }
quests[55299] = { id = 55299, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stinkgründler", description = "<Danielle Anglers interessiert sich bestimmt für diesen Fisch.>", sourceObjective = "Bringt den Fisch zu Danielle Anglers.\n\nBereitgestellter Gegenstand:", completion = "Dieser Fisch hat sich anscheinend an das Leben im flachen Wasser um die Müllhaufen gewöhnt. Er riecht abscheulich. Der höllische Gestank schützt ihn wahrscheinlich vor Räubern. Ich möchte ihn katalogisieren und wieder freilassen, bevor der Gestank an mir haften bleibt.", sourceObjectiveStatus = "unverified-source-field" }
quests[55300] = { id = 55300, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Kreislauf des Lebens" }
