quests[55305] = { id = 55305, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bolzenmaul", description = "<Danielle Anglers interessiert sich bestimmt für diesen Fisch.>", sourceObjective = "Bringt den Fisch zu Danielle Anglers.\n\nBereitgestellter Gegenstand:", completion = "Dieser Fisch wurde offenbar konstruiert! Er sieht nach komplizierter Verarbeitung aus. Ich möchte ihn katalogisieren und ihn zur weiteren Beobachtung wieder freilassen.", sourceObjectiveStatus = "unverified-source-field" }
quests[55306] = { id = 55306, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tümpelhopser", description = "<Danielle Anglers interessiert sich bestimmt für diesen Fisch.>", sourceObjective = "Bringt den Fisch zu Danielle Anglers.\n\nBereitgestellter Gegenstand:", completion = "Dieser Fisch kann scheinbar zwischen kleinen Wasserpfützen hin und her springen. Ich werde ihn katalogisieren und ihn in einer Pfütze in der Nähe freilassen. Mal sehen, wo er dann hinspringt!", sourceObjectiveStatus = "unverified-source-field" }
quests[55307] = { id = 55307, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dunkelgrottenaal", description = "<Danielle Anglers interessiert sich bestimmt für diesen Fisch.>", sourceObjective = "Bringt den Fisch zu Danielle Anglers.\n\nBereitgestellter Gegenstand:", completion = "Der Fisch hat sich so angepasst, dass er in den dunklen Höhlen von Mechagon überleben kann. Ich werde ihn katalogisieren und dann in einer Höhle in der Nähe freilassen.", sourceObjectiveStatus = "unverified-source-field" }
quests[55308] = { id = 55308, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mechanischer Kugelfisch", description = "<Danielle Anglers interessiert sich bestimmt für diesen Fisch.>", sourceObjective = "Bringt den Fisch zu Danielle Anglers.\n\nBereitgestellter Gegenstand:", completion = "Dieser merkwürdige mechanische Fisch modifiziert sich scheinbar selbst für das Leben in diesen Gewässern. Eine aufregende Entdeckung!", sourceObjectiveStatus = "unverified-source-field" }
quests[55309] = { id = 55309, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spuckender Clownfisch", description = "<Danielle Anglers interessiert sich bestimmt für diesen Fisch.>", sourceObjective = "Bringt den Fisch zu Danielle Anglers.\n\nBereitgestellter Gegenstand:", completion = "Dieser Fisch hat ein ungewöhnliches Verhaltensmuster entwickelt. Er imitiert vermutlich die Bewegungen der Kreaturen in seiner Umgebung. Ich werde ihn katalogisieren und ihn sofort wieder freilassen.", sourceObjectiveStatus = "unverified-source-field" }
quests[55310] = { id = 55310, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlammkarpfen", description = "<Danielle Anglers interessiert sich bestimmt für diesen Fisch.>", sourceObjective = "Bringt den Fisch zu Danielle Anglers.\n\nBereitgestellter Gegenstand:", completion = "Diesem Fisch ist etwas Abscheuliches passiert. Vielleicht solltet Ihr das Gewässer, in dem Ihr den Fisch gefunden habt, etwas genauer untersuchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[55311] = { id = 55311, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Starkstromkabeljau", description = "<Danielle Anglers interessiert sich bestimmt für diesen Fisch.>", sourceObjective = "Bringt den Fisch zu Danielle Anglers.\n\nBereitgestellter Gegenstand:", completion = "Der Fisch strahlt Elektrizität aus. Er hat wahrscheinlich an den Stromkabeln unter Wasser geknabbert. Ein interessanter Fund. Ich werde ihn sogleich katalogisieren!", sourceObjectiveStatus = "unverified-source-field" }
quests[55312] = { id = 55312, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Solarelritzel", description = "<Danielle Anglers interessiert sich bestimmt für diesen Fisch.>", sourceObjective = "Bringt den Fisch zu Danielle Anglers.\n\nBereitgestellter Gegenstand:", completion = "Dieser mechanische Fisch wird anscheinend durch Sonnenlicht angetrieben. Ich werde ihn katalogisieren und wieder in seinen Teich entlassen.", sourceObjectiveStatus = "unverified-source-field" }
quests[55313] = { id = 55313, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schmackhafte Stahlflosse", description = "<Danielle Anglers interessiert sich bestimmt für diesen Fisch.>", sourceObjective = "Bringt den Fisch zu Danielle Anglers.\n\nBereitgestellter Gegenstand:", completion = "Dieser Fisch sieht sehr gesund aus und schmeckt sicherlich vorzüglich. Ich werde ihn katalogisieren und ihn dann wahrscheinlich zum Abendessen kochen.", sourceObjectiveStatus = "unverified-source-field" }
quests[55319] = { id = 55319, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tonk der Tyrann", description = "<Dieser TK sieht aus, als wäre er eine gute Rennmaschine für das Eldoraso.\n\nCrash Mauschel an der Rennstrecke von Eldoraso entscheidet allerdings, was erlaubt ist und was nicht.>" }
