quests[55339] = { id = 55339, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Staubsaugen unter Wasser", description = "Die ionisierte Elritze ist die Geißel dieser Gewässer. Sie frisst den kompletten Meeresgrund ab und lässt nichts für andere Spezies übrig, die dann verhungern müssen.\n\nDieser Fisch hat kaum einen Nutzen, außer dass er Nahrung für größere Fische darstellt. Ich möchte gerne diese größeren Fische sehen und deshalb werden wir die Elritzen aus dem Wasser entfernen, um die großen Fische aus ihren Verstecken zu locken.\n\nFangen wir an, indem wir mit meinem Fischsauger ein paar ionisierte Elritzen für mich fangen.", sourceObjective = "Fangt 200 ionisierte Elritzen.", progress = "Habt Ihr was gefangen?", completion = "Mit diesen Elritzen können wir die Falle bauen.", sourceObjectiveStatus = "unverified-source-field" }
