quests[55345] = { id = 55345, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schüler der Dunklen Waldläuferin", description = "Dem Abgrund sei Dank, dass Ihr hier seid, Champion!\n\nMein Name ist Moorgoth, Sucher fürchterlicher Feinde an finstren Orten. Ihr werdet niemanden in der Volltrefferhütte treffen, der sich nicht für mich verbürgen würde.\n\nDie Dunkle Waldläuferin Velonara und ich, wir sind gute Freunde. Und ich befürchte, dass sie in Schwierigkeiten steckt.\n\nSie war zuletzt mit der Ausbildung eines Waldläuferlehrlings beschäftigt. Frisch neuerweckt, wie sie mir sagte. Jedenfalls ist ihr Schüler ihr davongelaufen, nachdem er einen Brief von seinem Bruder erhalten hatte. Und Velonara ist nach Tirisfal aufgebrochen, um ihn ausfindig zu machen.\n\nIch habe ein ganz schlechtes Gefühl bei der Sache. Könntet Ihr Euch vergewissern, dass sie in Sicherheit ist?", sourceObjective = "Findet die Dunkle Waldläuferin Velonara in Tirisfal.", sourceObjectiveStatus = "unverified-source-field" }
quests[55346] = { id = 55346, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schüler der Dunklen Waldläuferin", description = "Mein Name ist Moorgoth, Jäger fürchterlicher Feinde und Held der Volltrefferhütte.\n\nIhr seid ein gefeierter Champion der Allianz, doch ich habe gehört, dass Ihr denen helft, die in Gefahr sind. Also hört mich bitte an. \n\nIch bin gut mit einer Waldläuferin namens Velonara befreundet. Sie steht zwar in Diensten der Horde, aber ich versichere Euch, dass sie eine edle Seele hat.\n\nIn letzter Zeit war sie mit der Ausbildung eines jungen Waldläufers beschäftigt, der verschwunden ist, nachdem er einen Brief von seinem Bruder erhalten hatte. Velonara ist nach Tirisfal gereist, um ihn ausfindig zu machen.\n\nIch habe ein ganz schlechtes Gefühl bei der Sache. Würdet Ihr für mich nachsehen, ob sie in Sicherheit ist?", sourceObjective = "Findet die Dunkle Waldläuferin Velonara in Tirisfal.", sourceObjectiveStatus = "unverified-source-field" }
quests[55348] = { id = 55348, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorräte vom Rostbolzenwiderstand", description = "Der Widerstand weiß all die Hilfe zu schätzen, die Ihr uns zukommen lassen habt.\n\nBitte, nehmt diese Vorräte als Zeichen unserer Dankbarkeit und als Versprechen, dass es noch mehr davon gibt, wenn Ihr uns weiterhin helft.", sourceObjective = "Sprecht mit Prinz Erazmin im Rostbolzen, um Eure Belohnung zu erhalten.", completion = "Der Widerstand bleibt dank Eurer erfolgreichen Anstrengungen standhaft.\n\nDurch Eure Effizienz habt Ihr zusätzliche Ressourcen verdient.\n\nBitte setzt sie für Zwecke ein, die dazu optimiert sind, dem weiteren Erfolg des Widerstands zu dienen.", sourceObjectiveStatus = "unverified-source-field" }
quests[55350] = { id = 55350, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angriff: Vorstoß der Amathet", description = "Die Amathet wollen die Schmiede des Ursprungs für sich beanspruchen. Wir dürfen nicht zulassen, dass sie ihnen wieder in die Hände fällt!\n\nUnsere Leute verteidigen den Eingang, doch wenn die geballte Macht der Amathet gegen sie vorrückt, sind sie schnell überwältigt.\n\nTut, was Ihr könnt, um ihre Streitkräfte zurückzuschlagen, bevor es zu spät ist.", sourceObjective = "Schlagt den Angriff der Amathet in Uldum zurück.", completion = "Ha! Ihr habt diesen staubbedeckten Fanatikern gezeigt, wie ein wahrer Krieger aussieht.\n\nGut gemacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[55354] = { id = 55354, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Front am Vir'naal" }
