quests[55360] = { id = 55360, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das entsiegelte Grab" }
quests[55361] = { id = 55361, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der verlorene Schamane", description = "Entschuldigt bitte, {class}. Ich brauche Eure Hilfe.\n\nUnser Schamane, Scharfseher Ori, hat unser Lager vor einigen Tagen verlassen, um eine Störung der Elemente in der Nähe zu untersuchen. Er hat seinen jungen Lehrling Odari mitgenommen und ist seitdem nicht zurückgekehrt.\n\nIch führe eine Expedition bei der Suche nach ihnen an. Wir wollen sie sicher nach Hause bringen, in Nazjatar lauern schließlich viele Gefahren. <Ein so erfahrener/Eine so erfahrene:c> {class} wie Ihr ist uns mehr als willkommen.\n\nHelft Ihr uns bei der Suche und Rettung des vermissten Schamanen?", sourceObjective = "Findet Lehrling Odari im Drachenzahnbecken.", completion = "Gut, dass Ihr hier seid. Wir müssen uns sofort unterhalten. Ich fürchte um die Sicherheit meines Meisters.", sourceObjectiveStatus = "unverified-source-field" }
quests[55362] = { id = 55362, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elementarer Zorn", description = "Die Naga haben die Elemente erzürnt und die natürliche Ordnung durcheinandergebracht. Wir müssen das Gleichgewicht wiederherstellen, bevor es zu spät ist.\n\nEin Scharfseher hat eine enge Verbindung mit den Elementen. Als die Naga meinen Meister eingesperrt haben, wurde das natürliche Gleichgewicht gestört.\n\nNehmt den Stein der Elemente und nutzt ihn, um die wütenden Wasserelementare im Drachenzahnbecken zu befrieden.\n\nDie einzige endgültige Lösung ist, Scharfseher Ori zu retten und ihn lebendig zurückzubringen, aber der Gezeitenstein könnte uns wertvolle Zeit erkaufen.", sourceObjective = "Befriedet 8 Tidenwoger.", completion = "Gute Arbeit, Champion. Ich fühle, dass das Gleichgewicht der Elemente fast wieder in seinem natürlichen Zustand ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[55363] = { id = 55363, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rettet den Scharfseher", description = "Mein Meister, Scharfseher Ori, wird von den Schergen von Königin Azshara gefangengehalten.\n\nScharfseher Ori wurde gefangen genommen, als er ein heiliges Ritual abgehalten hat, bei dem er die Elemente um Führung bat. Ich konnte entkommen, aber das Ritual wurde nicht abgeschlossen.\n\nWenn wir meinen Meister nicht bald befreien, werden die Elemente noch unruhiger.\n\nDas Gleichgewicht der Elemente muss aufrechterhalten werden. Mir graut davor, was aus meinem Klan und unserer Bindung mit den Elementen wird, wenn wir Scharfseher Ori nicht zurückholen können.", sourceObjective = "Rettet Scharfseher Ori.", completion = "Ich will gar nicht wissen, was für ein Schicksal mich erwartet hätte, wenn Ihr nicht zu meiner Rettung gekommen wärt.", sourceObjectiveStatus = "unverified-source-field" }
quests[55373] = { id = 55373, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Haut sie aus dem Kasten", description = "Stahlarmplünderer haben all unsere Ersatzteile gestohlen und sie an Bondos Bande verkauft.\n\nLetzte Nacht haben sie all unsere Spinnenfedergetriebe gestohlen. Die Ersatzteile befinden sich in einigen Kisten, die von ihnen bewacht werden.\n\nIhr müsst unsere Getriebe zurückholen und diesen Stahlarmplünderern zeigen, dass sie sich mit den Falschen angelegt haben.", sourceObjective = "Reibt diese Stahlarmplünderer auf und holt uns 10 Spinnenfedergetriebe zurück.", progress = "Holt unser Getriebe zurück.", completion = "Jetzt können wir den Hauptfederantrieb des Reittiers zusammenbauen!", sourceObjectiveStatus = "unverified-source-field" }
quests[55374] = { id = 55374, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine unterirdische Störung", description = "Manifestation von Drachenessenz entdeckt. Ort: der Hochberg.\n\nErfolgreiche Bergung vorausgesetzt, deuten die Berechnungen auf eine Wahrscheinlichkeit von 92,7 Prozent, dass das Herz von Azeroth verstärkt wird.\n\nTheorie: Durch Kombination von Drachenessenz mit ausreichender Menge Azerit in der Herzschmiede könnten sich bisher unentdeckte Fähigkeiten im Herz manifestieren.\n\nWie Sprecher Magni sagen würde: \"An die Arbeit, Champion.\"", sourceObjective = "Reist zum Hochberg und untersucht die Essenz.", progress = "Was führt Euch her, {name}?", completion = "Wir müssen uns beeilen. Ich spüre, wie die Essenz meiner Brüder nach mir ruft.", sourceObjectiveStatus = "unverified-source-field" }
quests[55378] = { id = 55378, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rostbolzenrequisition: Schimmerschuppe", sourceObjective = "Bringt 20 Schimmerschuppen zu Gila Kurzschluss.", progress = "Ich habe eine dringende Anfrage von Tüftlermeister Oberfunks erhalten.\n\nDiese Güter werden benötigt!", completion = "Ich danke Euch, {name}. Eure Hilfe wird in unseren Aufzeichnungen festgehalten, damit die Nachwelt sie angemessen würdigen kann!", sourceObjectiveStatus = "unverified-source-field" }
quests[55379] = { id = 55379, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rostbolzenrequisition: Sternmoos", sourceObjective = "Bringt 20 Sternmoos zu Gila Kurzschluss.", progress = "Ich habe eine dringende Anfrage von Tüftlermeister Oberfunks erhalten.\n\nDiese Güter werden benötigt!", completion = "Ich danke Euch, {name}. Eure Hilfe wird in unseren Aufzeichnungen festgehalten, damit die Nachwelt sie angemessen würdigen kann!", sourceObjectiveStatus = "unverified-source-field" }
quests[55380] = { id = 55380, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rostbolzenrequisition: Sturmsilbererz", sourceObjective = "Bringt 10 Sturmsilbererz zu Gila Kurzschluss.", progress = "Ich habe eine dringende Anfrage von Tüftlermeister Oberfunks erhalten.\n\nDiese Güter werden benötigt!", completion = "Ich danke Euch, {name}. Eure Hilfe wird in unseren Aufzeichnungen festgehalten, damit die Nachwelt sie angemessen würdigen kann!", sourceObjectiveStatus = "unverified-source-field" }
quests[55381] = { id = 55381, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rostbolzenrequisition: Sturmsilbererz", sourceObjective = "Bringt 10 Sturmsilbererz zu Skaggit.", progress = "Gazlowes Bestellungen sind hier: Er will diesen Krempel so schnell wie möglich.\n\nHabt Ihr was davon?", completion = "Danke für Eure Hilfe.\n\nIch werde dafür sorgen, dass Gazlowe und Prinz Erazmin wissen, woher die Hilfe kam.", sourceObjectiveStatus = "unverified-source-field" }
quests[55382] = { id = 55382, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rostbolzenrequisition: Schimmerschuppe", sourceObjective = "Bringt 20 Schimmerschuppen zu Skaggit.", progress = "Gazlowes Bestellungen sind hier: Er will diesen Krempel so schnell wie möglich.\n\nHabt Ihr was davon?", completion = "Danke für Eure Hilfe.\n\nIch werde dafür sorgen, dass Gazlowe und Prinz Erazmin wissen, woher die Hilfe kam.", sourceObjectiveStatus = "unverified-source-field" }
quests[55383] = { id = 55383, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rostbolzenrequisition: Sternmoos", sourceObjective = "Bringt 20 Sternmoos zu Skaggit.", progress = "Gazlowes Bestellungen sind hier: Er will diesen Krempel so schnell wie möglich.\n\nHabt Ihr was davon?", completion = "Danke für Eure Hilfe.\n\nIch werde dafür sorgen, dass Gazlowe und Prinz Erazmin wissen, woher die Hilfe kam.", sourceObjectiveStatus = "unverified-source-field" }
quests[55384] = { id = 55384, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eingewöhnung", description = "Was auch immer Azshara vorhat, diese, ähm, großartige neue Landschaft, in der wir uns befinden, kommt leider ziemlich ungelegen. \n\nEs kommen zu viele zu nahe an unser Zuhause. Wir haben die meisten Flüchtlinge tiefer in die Höhlen gebracht.\n\nKönnt Ihr Telur fragen, ob er unsere Anrufmuschel reinbringen kann? \n\nNehmt Euch ein wenig von Slens Elixir und trefft Euch mit Vim.\n\nSobald sie steht, testet sie! \n\nIch bin dann mal weg auf einer Fortschrittskontrolle!", sourceObjective = "Stellt die Anrufmuschel auf und macht eine Runde.", completion = "Diesen Ton kann man nicht überhören, Festländer!", sourceObjectiveStatus = "unverified-source-field" }
quests[55385] = { id = 55385, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erkundungen in den Pferchen", description = "Einige unserer Späher sind nicht zurückgekehrt.\n\nSie haben die Sklavenunterkünfte der Zanj'ir im Auge behalten.\n\nDie Naga dort entführen unsere Leute. Sie brechen ihren Willen. Unsere Späher beobachten alles und wenn sich die Gelegenheit bietet, retten sie sie.\n\nIrgendwas geht da vor. Wir müssen sie nach Hause holen!", sourceObjective = "Findet die Späher.\n\nSolltet Ihr Neri aus den Augen verlieren, kehrt zur Muschel zurück, um sie zu rufen.", progress = "Haben wir alle gefunden?", completion = "Vielen Dank, dass Ihr uns helft, {name}.\n\nWir haben schon so viele verloren. Wir können jetzt nicht aufhören!", sourceObjectiveStatus = "unverified-source-field" }
quests[55390] = { id = 55390, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mein Traum in der Finsternis", description = "Der grüne Drachenschwarm bittet um Hilfe. Der Smaragdgrüne Traum, den er seit Ewigkeiten hütet, wurde von furchtbaren Leerenkreaturen überrannt.\n\nMerithra des Traums versucht, gegen die Bedrohung anzukämpfen, aber allein steht sie auf verlorenem Posten. Wenn Ihr das Herz von Azeroth mit der Kraft des smaragdgrünen Schwarms verstärken wollt, müsst Ihr erst Merithra helfen, ihn zu retten.\n\nSucht sie am Tempel von Elune in Val'sharah auf und unterstützt sie auf jede erdenkliche Weise.", sourceObjective = "Trefft Euch mit Merithra am Tempel von Elune in Val'sharah.", completion = "Danke für Euer Kommen, Champion. Meine Mutter vertraute einst den Sterblichen und ich stelle fest, dass ich mich erneut an sie wenden muss.\n\nIch weiß einfach nicht, wie ich diesen Kampf allein bestreiten soll.", sourceObjectiveStatus = "unverified-source-field" }
quests[55392] = { id = 55392, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In den Traumpfad", description = "Wir haben nur wenig Zeit, also werde ich mich kurz fassen.\n\nDer Smaragdgrüne Traum wird angegriffen. Die Schatten der Leere erheben sich, und nicht einmal der Traum liegt außerhalb ihrer Reichweite. Viele meiner Art wurden bereits getötet, und noch weitere sind in Gefahr.\n\nWir müssen den Traumpfad betreten und das, was von meinem Drachenschwarm noch übrig ist, retten, bevor es zu spät ist.", sourceObjective = "Sprecht mit Merithra, um den Smaragdgrünen Traumpfad zu betreten.", completion = "Nun seht Ihr, wie verzweifelt unsere Lage ist. Die Leere verschlingt uns!", sourceObjectiveStatus = "unverified-source-field" }
quests[55393] = { id = 55393, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Leere ausradieren", description = "Der grüne Drachenschwarm kann diese Flut aus Leerenkreaturen nicht allein aufhalten. Nicht mit unserer verminderten Kraft.\n\nBitte, stellt uns Eure Macht zur Verfügung und vertreibt sie vom Traumpfad, bevor sie in die wache Welt Einzug halten können.", sourceObjective = "Tötet Leereneindringlinge im Smaragdgrünen Traumpfad.", completion = "Ich danke Euch. Jetzt, da weniger dieser Leerenkreaturen vorhanden sind, können wir versuchen, den Traumpfad zu sichern.", sourceObjectiveStatus = "unverified-source-field" }
quests[55394] = { id = 55394, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Smaragdene Splitter", description = "Kalecgos hat mir erzählt, dass Ihr die Macht der Drachenschwärme in ihrer reinsten Form sucht. Möglicherweise gibt es hier etwas, das Euch helfen kann.\n\nFragmente unserer latenten Macht sind hier im Traum kondensiert.\n\nSie liegen überall verstreut im Traumpfad, wo Angehörige meiner Art gefallen sind. Innerhalb des Traums solltet Ihr diese Fragmente in ihrer Rohform benutzen können.", sourceObjective = "Sammelt Smaragdsplitter im Traumpfad.", progress = "Habt Ihr die Splitter eingesammelt?", completion = "Diese Macht gehörte einst meinem Schwarm. Sie wurde durch meine Mutter weitergereicht, als sie von der Titanin Eonar ermächtigt wurde.\n\n<Merithra senkt einen Moment lang ihren Kopf.>\n\nWenn Ihr unsere Welt nicht ohne sie retten könnt, müssen wir zuerst diese Fragmente vereinen.", sourceObjectiveStatus = "unverified-source-field" }
quests[55395] = { id = 55395, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schließt Eure Augen nicht", description = "Die Leere greift uns im Schlaf an! Jene, die von ihr umschlungen werden, wachen womöglich niemals wieder auf.\n\nSie können nur durch eine mächtige Magie wieder aufgeweckt werden, die unserem Drachenschwarm angeboren ist. Die Splitter, die sich in der Nähe unserer gefallen Schwarmangehörigen gebildet haben, könnten genau das sein, was wir brauchen.\n\nWenn wir uns dem Schlaf in der Leere hingeben, werden wir für immer verloren sein. Bitte, helft uns!", sourceObjective = "Weckt Thessera, Verdisa und Karkarius aus den Leerenträumen auf.", completion = "Karkarius... und Thessera ebenfalls? Ich hätte nie gedacht...\n\nEs betrübt mich sehr, dass jemand den Tod dem Kampf vorzieht. Dieses Leben mag voller Mühsal sein, doch es ist das einzige, das wir haben.\n\nIch bin dankbar, dass Ihr versucht habt, sie zu retten, auch wenn sie nicht gerettet werden wollten.", sourceObjectiveStatus = "unverified-source-field" }
quests[55396] = { id = 55396, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Stoff, aus dem die Träume sind", description = "Jetzt müssen die Smaragdfragmente, die Ihr gesammelt habt, nur noch in den See geworfen werden. Ich werde meine Macht benutzen, um sie miteinander zu verbinden.\n\nWenn es funktioniert, werden sie zu einer mächtigen Drachenschuppe vereint, die Ihr zur Verstärkung des Herzens von Azeroth verwenden könnt.\n\nIch glaube, meine Mutter wäre erfreut, dass ein Teil unserer Macht dazu beitragen wird, die Welt zu retten. Ich hoffe, sie wäre stolz auf uns.", sourceObjective = "Schleudert die Smaragdsplitter in den See und sammelt die Traumglanzdrachenschuppe ein.", progress = "Diese Gewässer mögen nicht mehr durch die Leere verderbt sein, doch der grüne Drachenschwarm muss wachsam bleiben, damit sie nie mehr zurückkehrt.", completion = "Ihr haltet die kondensierte Macht des grünen Drachenschwarms in Euren Händen, {name}. Ich vertraue darauf, dass Ihr sie zu einem guten Zweck nutzen werdet.", sourceObjectiveStatus = "unverified-source-field" }
quests[55397] = { id = 55397, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bevor ich erwache", description = "Es ist genau, wie ich es befürchtet hatte. Wir können die Splitter nicht miteinander verschmelzen, bis die Leere von hier vertrieben wurde.\n\nSchnell, bringt diese Ungeheuer zur Strecke. Ich gehe stark davon aus, dass eine Reaktion der Quelle der Verderbnis nicht lange auf sich warten lassen wird.", sourceObjective = "Vernichtet alle Griffe des Schreckens und den Leerenschrecken.", completion = "Wenn ich nur daran denke, dass so etwas Finsteres und Schreckliches hier so lange schwären konnte... Wir sind wirklich verloren.", sourceObjectiveStatus = "unverified-source-field" }
quests[55398] = { id = 55398, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das lange Erwachen", description = "Ihr könnt hier nichts weiter für uns tun, Champion. Ihr habt die Macht, nach der Ihr gesucht habt, und der Smaragdgrüne Traum kämpft gegen die Leere an.\n\nBringt diese Drachenschuppe zu Magni und den anderen. Wir treffen uns in der Herzkammer und ich helfe Euch, sie in das Herz von Azeroth zu integrieren.\n\nWas meinen Schwarm angeht, so muss unsere lange Wacht weitergehen, sonst verlieren wir uns in der Leere.", sourceObjective = "Kehrt mit der Traumglanzdrachenschuppe zu Merithra in der Herzkammer zurück.", completion = "Dieser Ort ist unglaublich, und ich bin stolz, an der Seite der anderen Drachenschwärme zur Verteidigung Azeroths beizutragen. Lasst uns hoffen, dass diese Essenz das Blatt zu unseren Gunsten wenden wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[55400] = { id = 55400, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nehmt meine Hand", description = "Unter uns liegt das frühere Heim des Drachen Neltharion. Ihr kennt ihn vielleicht als Todesschwinge.\n\nWenn Eure Freundin, die Titanenhüterin, eine magische Drachenessenz entdeckt hat, die in der Nähe kondensiert, könnte das ein Widerhall der Macht der Drachenschwärme sein. Solch eine Macht wird auch von anderen begehrt.\n\nDiese Kraft stammt wahrscheinlich aus dem stärksten Bereich des Horts: von dort, wo die zerfallenden Knochen meiner Art liegen, die durch Todesschwinges Zorn sterben mussten.\n\nWir müssen uns aufmachen, bevor die Essenz in die falschen Hände fällt.", sourceObjective = "Sprecht mit Navarrogg, um zum Drachenrücken in Neltharions Hort zu reisen.", completion = "Ich hoffe, Euer Weg nach unten war nicht so... steinig wie meiner.", sourceObjectiveStatus = "unverified-source-field" }
quests[55407] = { id = 55407, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Rücken beruhigen", description = "Es ist offensichtlich, dass die Lage hier verzweifelt ist.\n\nDie Macht des schwarzen Drachenschwarms hallt überall um uns herum wider und die Erde bebt als Reaktion darauf.\n\nIch hörte Erzählungen über Risse wie diese in Kul Tiras und Zandalar. Die Elementare wurden in die Raserei getrieben und versperren uns den Weg auf unserer Suche nach der Essenz.\n\nWenn wir das schwache Gleichgewicht der Elemente hier bewahren wollen, müssen die Wunden geheilt werden, {name}.", sourceObjective = "Versiegelt die Azeritrisse im Drachenrücken.", progress = "Sind die Wunden geheilt, {name}?", completion = "Die Risse sind geschlossen? Gut. Wir können weitermachen.", sourceObjectiveStatus = "unverified-source-field" }
quests[55424] = { id = 55424, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aspirantin Elynna", description = "{name}! Ihr seid in den Schlund zurückgekehrt! Möge der Ruhm mit Euch sein!\n\nIch habe Neuigkeiten. Offenbar wird eine der Aspirantinnen, die nach dem Angriff auf Ehrenschleier verschollen war, hier im Arsenal des Kerkermeisters festgehalten. Ihr Name ist Elynna, und sie befindet sich auf dem zehnten Stock.\n\nDas ist alles, was ich Euch aktuell sagen kann. Wir sprechen uns wieder, wenn ich mehr weiß.", sourceObjective = "Findet Aspirantin Elynna auf dem zehnten Stock des Turms des Kerkermeisters.", sourceObjectiveStatus = "unverified-source-field" }
quests[55425] = { id = 55425, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Unbeugsamen beugen", description = "Jetzt, da die Wunden geschlossen sind, kann ich deutlich die Drachenessenz spüren. Leider scheint sie von dem irdenen Riesen dort vor uns auszugehen.\n\nIch werde die Kreatur ansprechen. Hoffen wir, dass sie vernünftigen Argumenten zugänglich ist... aber seid auf alles gefasst.\n\nAls Todesschwinge die Weltensäule in Tiefenheim zerschmetterte, hat er sich den Zorn der Steinmutter und ihrer Streitkräfte zugezogen. Ich fürchte, dieses Wesen könnte mir die Schuld für die Verbrechen meines Vaters geben.", sourceObjective = "Stellt Ma'haat den Unbeugsamen im Drachenrücken.", progress = "Die Essenz meines Schwarms ist wirklich sehr mächtig.", completion = "Jetzt, da wir die Essenz besitzen, bete ich, dass die Erde wieder Frieden finden kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[55426] = { id = 55426, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was wächst denn da?", description = "<Der kleine Samen beginnt zu treiben. Vielleicht könnte man ihn irgendwo in der Nähe einpflanzen.>", sourceObjective = "Pflanzt den keimenden Samen in fruchtbare Erde.", progress = "Was habt Ihr für mich?", completion = "So, was haben wir denn hier? In der Tat eine sehr seltene Pflanze!\n\nKorallenpeitscher sind eine erstaunliche Art. Sie wachsen nach jeder Mahlzeit extrem schnell und gewinnen erstaunlich an Größe und Stärke.\n\nDie größten von ihnen sind wirklich außergewöhnlich, aber auch sehr gefährlich. Also bitte verantwortungsvoll füttern.", sourceObjectiveStatus = "unverified-source-field" }
quests[55431] = { id = 55431, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eroberungsbelohnung", sourceObjective = "Eure Kühnheit auf dem Schlachtfeld ist ohnegleichen.", sourceObjectiveStatus = "unverified-source-field" }
quests[55432] = { id = 55432, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eroberungsbelohnung", sourceObjective = "Eure Kühnheit auf dem Schlachtfeld ist ohnegleichen.", sourceObjectiveStatus = "unverified-source-field" }
