quests[55451] = { id = 55451, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Farbphiole: Feuerballrot", description = "<Der mitreißende Martini kann das sicher gut gebrauchen.>", sourceObjective = "Bringt den Gegenstand dem mitreißenden Martini.\n\nBereitgestellter Gegenstand:", completion = "Was für eine gewagte Farbe für eine Mechanokatze. Ich kann mir gut vorstellen, wie Ihr sie reitet!", sourceObjectiveStatus = "unverified-source-field" }
quests[55452] = { id = 55452, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Farbphiole: Teufelsminzgrün", description = "<Der mitreißende Martini kann das sicher gut gebrauchen.>", sourceObjective = "Bringt den Gegenstand dem mitreißenden Martini.\n\nBereitgestellter Gegenstand:", completion = "Eine wunderbare Farbwahl. Ich kann die Teufelsmacht beinahe schmecken!", sourceObjectiveStatus = "unverified-source-field" }
quests[55454] = { id = 55454, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Farbphiole: Limonadenstahl", description = "<Der mitreißende Martini kann das sicher gut gebrauchen.>", sourceObjective = "Bringt den Gegenstand dem mitreißenden Martini.\n\nBereitgestellter Gegenstand:", completion = "Was für eine geschmackvolle Farbe für eine Mechanokatze!", sourceObjectiveStatus = "unverified-source-field" }
quests[55455] = { id = 55455, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Farbphiole: Mechagongold", description = "<Der mitreißende Martini kann das sicher gut gebrauchen.>", sourceObjective = "Bringt den Gegenstand dem mitreißenden Martini.\n\nBereitgestellter Gegenstand:", completion = "Gut oder böse... auf jeden Fall eine Ansage!", sourceObjectiveStatus = "unverified-source-field" }
quests[55456] = { id = 55456, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Farbphiole: Kupferglanz", description = "<Der mitreißende Martini kann das sicher gut gebrauchen.>", sourceObjective = "Bringt den Gegenstand dem mitreißenden Martini.\n\nBereitgestellter Gegenstand:", completion = "Eine einmalige Wahl für alle, die anders sein wollen.", sourceObjectiveStatus = "unverified-source-field" }
quests[55457] = { id = 55457, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Farbphiole: Oberorange", description = "<Der mitreißende Martini kann das sicher gut gebrauchen.>", sourceObjective = "Bringt den Gegenstand dem mitreißenden Martini.\n\nBereitgestellter Gegenstand:", completion = "Einer meiner Favoriten!", sourceObjectiveStatus = "unverified-source-field" }
quests[55462] = { id = 55462, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf der Reisenden", description = "Seid gegrüßt, Kleinling.\n\nDie große Reisende hat darum gebet'n, Euch abzuhol'n. Sie hat 'ne Aufgabe für Euch un' die Kleine.\n\nJo'noks Loa is' geduldig, aber er würd sie nicht wart'n lass'n.", sourceObjective = "Sprecht mit Torcali in den Wilden Landen.", completion = "<Das große Terrorhorn betrachtet Euch mit einem riesigen Auge. Eine Stimme breitet sich in Euren Gedanken aus.>\n\nMir gefällt, was ich sehe. Ich möchte Euch jetzt um mehr bitten.", sourceObjectiveStatus = "unverified-source-field" }
quests[55463] = { id = 55463, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hilfe von Nordrassil", description = "Seht Euch nur an, was sie der Insel angetan haben, {name}.\n\nDie Natur ist beinahe ausgelöscht und ihr Todesschrei prallt an den tauben Ohren der Mechagnome einfach ab.\n\nAber ich habe die klitzekleinen Tierchen von Mechagon gehört und Hilfe von weit her geholt!\n\nEs wird nicht einfach sein, das Gleichgewicht in so einem verwüsteten Land wiederherzustellen. Die Natur wurde hier tief getroffen und schwer verwundet.\n\nZum Glück sind wir nicht allein. Ich habe lebenden Saft von Nordrassil, dem Weltenbaum vom Hyjal, mitgebracht. Benutzt ihn, um den Wald wieder wachsen zu lassen und die Erholung der Natur auf dieser Insel zu beschleunigen.", sourceObjective = "Tötet 8 Sägeblattroder und benutzt den lebenden Saft von Nordrassil, um 8 Baumstümpfe wieder wachsen zu lassen.", completion = "Ein kleiner Schritt in Richtung Wiederherstellung des Gleichgewichts in Mechagon.\n\nIch danke Euch, {name}. Genauso wie die vielen lieben kleinen Tierchen, die auf den Bäumen, die Ihr habt wachsen lassen, ein neues Zuhause finden werden. Ich werde unseren Fortschritt den Druiden von Nordrassil übermitteln.", sourceObjectiveStatus = "unverified-source-field" }
quests[55465] = { id = 55465, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wir müssen tiefer hinein", description = "Diese Splitter können in ihrem augenblicklichen Zustand nur begrenzt etwas bewirken. Sie sind zerbrochen und überall verstreut... ähnlich wie die Angehörigen meiner Art.\n\nWir müssen sie wieder zusammenbringen.\n\nLasst uns tiefer in den Smaragdgrünen Traum vordringen. Ich kenne dort einen Ort, an dem wir die Splitter zu einer Drachenschuppe zusammenfügen können. Damit könnt Ihr dann das Herz von Azeroth mit der Essenz meines Drachenschwarms verstärken. Wir müssen uns zum uralten Herz des Traums begeben, wo meine Mutter einst ruhte.\n\nSprecht mich an, wenn Ihr bereit seid, tiefer einzutauchen.", sourceObjective = "Sprecht mit Merithra, um tiefer in den Smaragdgrünen Traum einzudringen.", completion = "Das Ausmaß der Verderbnis ist noch schlimmer, als ich dachte. Meine Mutter hat diesen Ort früher geliebt... und nun droht er im Würgegriff der Leere zu verdorren.", sourceObjectiveStatus = "unverified-source-field" }
quests[55466] = { id = 55466, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vuk'laz der Erdbrecher" }
quests[55469] = { id = 55469, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nach Zin-Azshari", description = "Wir brauchen etwas, um mit der Wächterin des Gezeitensteins fertigzuwerden, {name}.\n\nUnsere neuen Verbündeten hier sagen, es gäbe eine Nagaenklave in den Ruinen von Zin-Azshari. Wenn es etwas geben sollte, das mächtig genug ist, Azsharas Zauberei zu bekämpfen, muss es sich in den Ruinen ihrer Hauptstadt befinden.\n\nDie Erste Arkanistin wird Euch begleiten, Champion. Sie ist bestens darauf vorbereitet, Euch bei historischen Fragen und magischen Angelegenheiten zur Seite zu stehen.\n\nViel Glück.", sourceObjective = "Trefft die Erste Arkanistin Thalyssra in den Ruinen von Zin-Azshari.", completion = "Ist das, was ich denke, das es ist?", sourceObjectiveStatus = "unverified-source-field" }
quests[55481] = { id = 55481, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufklärung im Palast", description = "Wir können uns hier nicht ewig verstecken, {name}. Wir müssen uns um Azshara kümmern.\n\nWir werden ihren Palast angreifen müssen, auch wenn wir nicht wissen, wie ihre Verteidigungsmaßnahmen aussehen. Ich habe in Eurer Abwesenheit einen Spähtrupp entsandt, aber er hat sich noch nicht zurückgemeldet.\n\nIch kann mir keine weiteren Verluste leisten. Sprecht mit Geistwandler Ussoh. Mithilfe seiner Fähigkeiten können wir die Späher ausfindig machen.", sourceObjective = "Sprecht mit Geistwandler Ussoh, um den Spähtrupp ausfindig zu machen.", progress = "Habt Ihr schon mit Ussoh gesprochen?", completion = "Der Gezeitenstein! Natürlich...", sourceObjectiveStatus = "unverified-source-field" }
quests[55482] = { id = 55482, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hallo? Vermittlung?", description = "Ein Kommunikationskristall! Sie haben so lange überdauert?\n\nWir haben sie zur Kommunikation benutzt. Mit ihnen konnten wir Projektionen von uns selbst auf andere Kristalle in der Nähe werfen und Personen auf der anderen Seite sehen und mit ihnen reden.\n\n<Thalyssra untersucht den Kristall für einen Moment.>\n\nDieser Kristall ist schon lange ohne Magie. Wir brauchen eine Machtquelle, am besten etwas sehr Altes.\n\nSeht Euch mal um, aber seid vorsichtig! Hier draußen ist es verdächtig still...", sourceObjective = "Durchsucht die Ruinen von Kal'methir nach magischen Relikten.", progress = "Habt Ihr etwas gefunden, dass den Kristall wieder aktivieren kann?", completion = "Das sollte reichen, wenn sie genug Kraft haben ...", sourceObjectiveStatus = "unverified-source-field" }
quests[55485] = { id = 55485, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Entsetzen in der Tiefe", description = "Azshara weiß jetzt, dass wir hier sind. Aber wir müssen weitermachen.\n\nSeid jedoch vorsichtig. Es kommt eine merkwürdige... Falschheit aus dem Wasser. Sie ist anders als die alte Magie, aber noch älter und schrecklicher.\n\nÜberquert die Kanäle und findet die Quelle der Verderbnis. Wenn wir Zin-Azshari durchsuchen sollen, dürfen wir nicht zulassen, dass irgendwelche Relikte in die Hände dunkler Mächte fallen.", sourceObjective = "Besiegt 10 verderbte Kreaturen und die Quelle der Verderbnis.", completion = "Sein Einfluss wächst...", sourceObjectiveStatus = "unverified-source-field" }
quests[55486] = { id = 55486, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geheimnisse der Telemantie", description = "Den Nachtgeborenen ist dieses Land nicht unbekannt. Vor langer, langer Zeit war das unsere Hauptstadt.\n\nVor der Zerschlagung und dem Aufstellen des Schildes über Suramar konnten wir frei nach Zin-Azshari reisen. Oculeth hatte in diesem Anwesen eine Werkstatt. \n\nVielleicht birgt sie einige Geheimnisse oder Magie, die durch die Überlebenden nicht gestört wurde.", sourceObjective = "Untersucht Oculeths alte Werkstatt.", progress = "Habt Ihr die Werkstatt schon gefunden?", completion = "Warum überrascht mich das nicht. Trotzdem können diese Notizen nützlich sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[55488] = { id = 55488, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sprecht mit den Toten", description = "So viele Seelen sind in den Wellen verschwunden. Zu viele wurden für Azsharas kranke Ehrsucht geopfert.\n\nMerkwürdig, dass die Geister noch nicht von hier verschwunden sind. Ich frage mich, ob sie überhaupt wissen, dass sie tot sind?\n\nIhr Wissen wird uns allerdings von Nutzen sein. Wenn Ihr die Geister befragt, geben Sie uns vielleicht wertvolle Hinweise.", sourceObjective = "Sprecht mit den Geistern auf dem Anwesen der Hochgeborenen, um etwas Nützliches zu erfahren.", completion = "Die Wurfspeere? Ich dachte, sie wären verloren!", sourceObjectiveStatus = "unverified-source-field" }
quests[55489] = { id = 55489, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Report der Hofdame", description = "Die Wurfspeere von Suramar!\n\nAzshara höchstselbst hat sie geführt. Sie bergen eine unglaubliche magische Macht. Sie war immer stolz darauf, ihren Lieblingen bestimmte Vorzüge zu gewähren, aber ich hätte niemals gedacht, dass sie so ein wertvolles Artefakt wie einen ihrer Wurfspeere weitergibt. Dieser Feind muss wahrlich beeindruckend sein.\n\nAll dem zum Trotz, {name}, können wir uns diese Gelegenheit nicht entgehen lassen. Besiegt die Hofdame und bergt das Relikt!", sourceObjective = "Bergt den Wurfspeer von Suramar.", progress = "Wir dürfen sie nicht entkommen lassen.", completion = "Das könnte funktionieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[55490] = { id = 55490, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der ganz große Wurf", description = "Die Wurfspeere gehörten zu den feinsten Schöpfungen vor der Zerschlagung. Ihre Magie ist uralt und mächtig. Vielleicht sogar stark genug, Azsharas Zauberschutze zu zerstören.\n\nSchnell zurück nach Neuheim. Wir müssen den anderen von unserem Erfolg hier berichten. Sehr gute Arbeit von Euch.", sourceObjective = "Kehrt zu Lor'themar Theron in Neuheim zurück.", completion = "Damit können wir den Gezeitenstein sichern.", sourceObjectiveStatus = "unverified-source-field" }
quests[55497] = { id = 55497, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein vertrautes Gesicht", description = "Mit der Essenz der Magie des schwarzen Drachenschwarms geht man nicht leichtfertig um, {name}.\n\nMein Schwarm ist in der Vergangenheit dunklen Mächten zum Opfer gefallen. Ich schulde es meinen Brüdern und Schwestern, dass unsere Macht nie wieder für böse Zwecke missbraucht wird.\n\nIch möchte Euch begleiten und Eure Verbündeten kennenlernen. Vielleicht könnt Ihr mit meiner Hilfe diese Essenz verwenden, um unsere Welt zu beschützen.", sourceObjective = "Trefft Euch mit Geistwandler Ebenhorn und Magni Bronzebart in der Herzkammer.", completion = "Ich mag Euren Taurenfreund. Und ich habe die Hoffnung, dass er von der Verderbnis verschont bleibt!\n\nAlso, es ist an der Zeit zu sehen, was MUTTER mit der Essenz anstellen kann!", sourceObjectiveStatus = "unverified-source-field" }
quests[55498] = { id = 55498, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schimmernde Kristall", description = "Obwohl der Kristall Euch zunächst vertraut erscheint, offenbart sich bei Kontakt mit Eurem Finger, dass er viel mehr ist als ein gewöhnlicher Kristall. Bilder einer großen, verlorenen Zivilisation erscheinen vor Euch. In jeder Richtung könnt Ihr gold glänzende Befestigungen erkennen, prächtige violette Federn fallen vereinzelt vom Himmel. Ihr hört Schlachtenlärm in der Entfernung, der anschwillt und in einer donnernden Explosion mündet, die alle Eure Sinne betäubt, so dass Ihr nur noch helles Weiß vor Euren Augen seht.\n\nAls Ihr wieder zu Euch kommt, fühlt Ihr, dass Euch etwas nach Ashran zieht.", sourceObjective = "Bringt den schimmernden zeitverzerrten Kristall zu Tempra am Sturmschild.", completion = "Ich war schon immer vom Zeitalter der Ordnung fasziniert, aber ich habe noch nie so einen interessanten Kristall gefunden.\n\nich werde dieses Artefakt studieren. Vielleicht habe ich wirklich die richtige Zeit gewählt, um meine Nachforschungen voranzutreiben.", sourceObjectiveStatus = "unverified-source-field" }
quests[55499] = { id = 55499, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schimmernde Kristall", description = "Obwohl der Kristall Euch zunächst vertraut erscheint, offenbart sich bei Kontakt mit Eurem Finger, dass er viel mehr ist als ein gewöhnlicher Kristall. Bilder einer großen, verlorenen Zivilisation erscheinen vor Euch. In jeder Richtung könnt Ihr gold glänzende Befestigungen erkennen, prächtige violette Federn fallen vereinzelt vom Himmel. Ihr hört Schlachtenlärm in der Entfernung, der anschwillt und in einer donnernden Explosion mündet, die alle Eure Sinne betäubt, so dass Ihr nur noch helles Weiß vor Euren Augen seht.\n\nAls Ihr wieder zu Euch kommt, fühlt Ihr, dass Euch etwas nach Ashran zieht.", sourceObjective = "Bringt den schimmernden zeitverzerrten Kristall zu Kronnus am Kriegsspeer.", completion = "Das Zeitalter der Ordnung prägte die Zukunft Draenors in zahlreichen Zeitlinien in vielerlei Hinsicht. Mit jedem neuen Artefakt, das wir finden, lernen wir mehr über seine Entwicklung und seinen Untergang, sowie über Gemeinsamkeiten und Unstimmigkeiten der einzelnen Zweige der verschiedenen Zeitlinien.\n\nDieses Artefakt ist dabei ohne Zweifel das seltsamste, das mir bisher untergekommen ist. Ihr habt gut daran getan, es zu mir zu bringen.", sourceObjectiveStatus = "unverified-source-field" }
quests[55500] = { id = 55500, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Freundesrettung", description = "In der Höhle vor uns halten sie Mak gefangen.\n\nSie foltern uns. Sie brechen uns.\n\nSie dürfen uns nicht auch noch Mak wegnehmen.", sourceObjective = "Tötet die Heroldin der Königin und befreit Mak.", completion = "Wir stehen tief in Eurer Schuld, Festländer.", sourceObjectiveStatus = "unverified-source-field" }
quests[55503] = { id = 55503, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Terrorhorn und der Saurid", description = "<Eine sanfte Stimme breitet sich in Euren Gedanken aus.>\n\nIch bin sehr zufrieden mit Euren Bemühungen. Er wird die Güte, die Ihr ihm entgegengebracht habt, nicht so schnell vergessen... und deshalb wird er auch mich nicht so schnell vergessen.\n\nJetzt wird Eure Reise Euch nach Süden führen. Ich kann einen meiner Wegschreine nicht mehr spüren. Falls Ihr herausfinden könnt, was ihm widerfahren ist, und ihn wiederherstellen könnt, wäre ich sehr dankbar.", sourceObjective = "Findet heraus, welches Schicksal den zentralen Wegschrein ereilt hat.", completion = "<Eine belustigte Stimme erklingt in Euren Gedanken.>\n\nAh, der Trickser Jani wollte sich auf meine Kosten einen Scherz erlauben. Ich nehme an, das ist die Revanche dafür, dass ich ihm auf den Schwanz getreten bin.\n\nIch danke Euch. Dieser Schrein wird den Zandalari wieder gute Dienste leisten.", sourceObjectiveStatus = "unverified-source-field" }
quests[55504] = { id = 55504, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wegschreine von Zuldazar", description = "<Eine ebenso ruhige wie donnernde Stimme ertönt in Eurem Geist.>\n\nMein Kind wächst unter Eurer Obhut auf. Das freut mich. Und jetzt benötige ich Eure Hilfe.\n\nEs gab einst eine Zeit, in der die Straßen von Zandalar unter meinem Schutz standen. Wer auf ihnen reiste, huldigte mir, und im Gegenzug gab ich meinen Segen. Nur noch wenige bereisen sie dieser Tage.\n\nMeine Schreine existieren noch, aber ihr Zweck ist vergessen. Ihr werdet mir helfen, sie wiederherzustellen.\n\nBeginnt im Norden. Kümmert Euch um den Wegschrein dort. Wenn Euch verirrte Reisende begegnen, sorgt dafür, dass sie meinen Segen durch Euch erfahren.", sourceObjective = "Stellt den nördlichen Wegschrein wieder her und unterstützt alle Reisenden, denen Ihr begegnet.", progress = "Habt Ihr die Kräuter?", completion = "Die meisten meiner Waren sin' durch die Hitze und den Regen verdorb'n. Aber nehmt das hier als Anerkennung.\n\nJetzt könn' wir endlich nach Hause.", sourceObjectiveStatus = "unverified-source-field" }
quests[55505] = { id = 55505, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gedenken an Roo'li", description = "Ich sollte 'ne Dinomantin werd'n un' Roo'li sollte mit mir bei meiner Ausbildung aufwachs'n.\n\n<Koo'li schüttelt ihren Kopf.>\n\nAber diese Zukunft is' dahin. Bitte nehmt ihn und findet 'n guten Platz, um ihn zu beerdig'n.\n\nIch... kann das nich'. Die Schande is' zu groß.", sourceObjective = "Bringt Roo'lis Überreste zu Torcali.", progress = "<Der große Terrorhornloa starrt auf Euch herab.>\n\nWas habt Ihr mir mitgebracht, {name}?", completion = "<Torcalis Stimme dringt in Euren Geist ein.>\n\nSeine Zeit auf dieser Welt ist um, aber er wird nicht vergessen werden. Er kehrt in die Erde zurück und sein Geist wird weiterleben.", sourceObjectiveStatus = "unverified-source-field" }
quests[55506] = { id = 55506, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Straße endet", description = "<Eine warme Stimme erklingt in Eurem Geist.>\n\nEs gibt noch einen weiteren Wegschrein in dieser Region, der Eurer Aufmerksamkeit bedarf.\n\nFolgt dieser Straße, bis Ihr Euch ihrem Ende am Hafen von Zandalar nähert.\n\nDort, am Anfang und Ende so mancher Reise, wurde einer meiner meistbesuchten Schreine errichtet. Stellt ihn wieder her und sorgt dafür, dass alle müden Reisenden meinen Segen erhalten.\n\nWir sprechen wieder miteinander, wenn Ihr fertig seid.", sourceObjective = "Stellt den südlichen Wegschrein wieder her und unterstützt alle Reisenden, denen Ihr begegnet.", completion = "Ich hätt' ihn beschütz'n soll'n, aber er is' nich' zurückgewich'n. Tapferes kleines Ding.\n\n<Koo'li tätschelt Roo'lis Kopf.>", sourceObjectiveStatus = "unverified-source-field" }
quests[55507] = { id = 55507, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Torcalis Segen", description = "<Torcalis Stimme dringt in Euren Geist ein.>\n\nEure Taten bezeugen Eure Absichten, {name}.\n\nIch sehe, dass mein Kind den Schutz genießt, den es zum Heranwachsen benötigt. Und es wird heranwachsen.\n\nIn den kommenden Tagen wird es die Stärke wiedererlangen, die ihr zur Verfügung gestanden hätte, wenn die Natur ihren normalen Lauf hätte nehmen können. Kümmert Euch um mein Kind, gewinnt seine Loyalität und ich werde Euch erlauben, es an Eurer Seite zu behalten.\n\nDas ist mein Geschenk an Euch.\n\nGeht nun. Sie wird Euch zu mir bringen, wenn die Zeit gekommen ist.", sourceObjective = "Kehrt zum Spross von Torcali in seinem Nest im Kriegsbestienkral zurück.", completion = "<Der Spross von Torcali schaut Euch vertrauensvoll an.>", sourceObjectiveStatus = "unverified-source-field" }
quests[55508] = { id = 55508, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sieg in Tausendwinter", description = "Hauptmann Zanneth mag vielleicht zufrieden damit sein, einen Haufen Hordeleichen vor sich liegen zu haben, doch die Kontrolle über die Tausendwinterfestung zu erlangen, ist für die Expedition Valianz von äußerster Wichtigkeit. Kümmert Euch darum, dass sie weiterhin in unseren Händen bleibt.\n\nGlaubt jedoch bloß nicht, dass wir Euch einfach so herumstehen lassen werden, während Eure Mitstreiter die Drecksarbeit für Euch erledigen. Wenn Ihr bis zum Ende der Schlacht nicht mindestens ein Rekrut zweiten Grades seid, dann braucht Ihr nicht zurückkommen.", sourceObjective = "Gewinnt einen Kampf auf dem Schlachtfeld in Tausendwinter. Ihr müsst an der Schlacht teilgenommen haben, um für den Sieg belohnt zu werden. Die Quest kann nur automatisch abgeschlossen werden, während Ihr Euch in der Schlacht um Tausendwinter befindet.", completion = "Genau das, was ich hören wollte! Ein Sieg auf dem Tausendwintersee - selbst ein vorübergehender - ist ein äußerst wichtiger Bestandteil unserer Gesamtstrategie gegen die Horde.", sourceObjectiveStatus = "unverified-source-field" }
quests[55509] = { id = 55509, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sieg in Tausendwinter", description = "Dardosh mag es zwar genügen, unsere Feinde zu töten, doch es ist von äußerster Wichtigkeit, dass wir die Tausendwinterfestung kontrollieren. Tut, was auch immer nötig ist, damit Tausendwinter uns gehört.\n\nGlaubt jedoch bloß nicht, dass wir Euch einfach so herumstehen lassen werden, während Eure Mitstreiter die Drecksarbeit für Euch erledigen. Wenn Ihr bis zum Ende der Schlacht nicht mindestens ein Rekrut zweiten Grades seid, dann braucht Ihr nicht zurückkommen.", sourceObjective = "Gewinnt einen Kampf auf dem Schlachtfeld in Tausendwinter. Ihr müsst an der Schlacht teilgenommen haben, um für den Sieg belohnt zu werden. Die Quest kann nur automatisch abgeschlossen werden, während Ihr Euch in der Schlacht um Tausendwinter befindet.", completion = "Ihr habt heute wahrlich etwas Großartiges fertiggebracht. Euer Opfer wird geschätzt!", sourceObjectiveStatus = "unverified-source-field" }
quests[55510] = { id = 55510, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Keine Gnade für die Gnadenlosen", description = "Willkommen in Tausendwinter, {name}. Eure Mission hier ist einfach: Besiegt zehn der besten Kämpfer, die die Horde zu bieten hat. Nun geht! Zum Sieg der Allianz!", sourceObjective = "Hauptmann Zanneth in der Tausendwinterfestung möchte, dass Ihr 10 Mitglieder der Horde tötet. Die Quest kann nur automatisch abgeschlossen werden, während Ihr Euch in der Schlacht um Tausendwinter befindet.", sourceObjectiveStatus = "unverified-source-field" }
quests[55511] = { id = 55511, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tötet sie alle!", description = "Willkommen in Tausendwinter, {name}. Kriegsfürst Garrosh verlangt nur eins: Tötet sie alle!\n\nKehrt zu mir zurück, wenn die zehn stärksten Kämpfer der Allianz tot sind.", sourceObjective = "Kommandant Dardosh in Tausendwinter möchte, dass Ihr 10 Mitglieder der Allianz tötet. Die Quest kann nur automatisch abgeschlossen werden, während Ihr Euch in der Schlacht um Tausendwinter befindet.", sourceObjectiveStatus = "unverified-source-field" }
quests[55516] = { id = 55516, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geistesblitz", description = "{name}, ich benötige Eure Hilfe.\n\nVor Kurzem haben einige der Ortungsrelais, die ich nach dem unglücklichen Vorfall mit Sargeras installiert habe, eine Energiesignatur aufgezeichnet.\n\nDie anfängliche Diagnose hat ergeben, dass sie wahrscheinlich von Hati stammen, einer legendären Kreatur aus elektrischer Magie. Dieser Wolf stand in Verbindung mit dem Artefakt Titanenblitz, das entscheidend dazu beitrug, die Legion zu bezwingen!\n\nHatis Geist ist noch immer an den Kern des Titanenblitzes gebunden. Also werde ich Eure Hilfe brauchen. Trefft mich in der Bibliothek in den Sturmgipfeln, sobald Ihr könnt!", sourceObjective = "Trefft Euch mit Mimiron in der Bibliothek des Erfinders in den Sturmgipfeln.", completion = "Ohne Bronzebart wäre unser wissenschaftliches Team einfach nicht vollständig.\n\nLasst uns anfangen!", sourceObjectiveStatus = "unverified-source-field" }
quests[55517] = { id = 55517, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Farbphiole: Klotzbronze", description = "<Der mitreißende Martini kann das sicher gut gebrauchen.>", sourceObjective = "Bringt den Gegenstand dem mitreißenden Martini.\n\nBereitgestellter Gegenstand:", completion = "Einer meiner Favoriten!", sourceObjectiveStatus = "unverified-source-field" }
quests[55519] = { id = 55519, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine frische Wunde", sourceObjective = "Trefft Euch mit Magni bei Nordrassil auf dem Hyjal.", completion = "Wenn wir es nicht schaffen, diese Wunden zu heilen, wird der Weltenbaum vielleicht nicht mehr lange stehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[55520] = { id = 55520, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heilung von Nordrassil", description = "Die Azeritelementare rasten durch Azeroths Schmerz komplett aus. Sie bedrohen die Geister der Natur, die den Weltenbaum beschützen.\n\nDie Wurzeln von Nordrassil reichen tief in die Erde hinab und werden von diesen heiligen Gewässern genährt. Der Baum muss zum Wohl der Weltenseele von Azeroth verteidigt werden!\n\nBefriedet die ruhelosen Elementare und nutzt Euer Herz von Azeroth, um die Wunden, die Ihr findet, zu heilen. Der Hyjal darf nicht zu einer weiteren klaffenden Wunde wie Silithus werden!", sourceObjective = "Besiegt die Azeritelementare und versiegelt Azeroths Wunden bei Nordrassil.", progress = "Es wird immer schlimmer. Wenn sich zu viele Wunden öffnen, können wir diese Kaskade vielleicht nicht mehr aufhalten.", completion = "Ihr habt es geschafft, {name}! Ich fühle, wie ihr Schmerz nachlässt.\n\nUnd das Herz scheint jetzt stärker zu sein als zuvor!", sourceObjectiveStatus = "unverified-source-field" }
quests[55521] = { id = 55521, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Macht es azerichtig", description = "Unglaublich! Ihr habt verhindert, dass sich die Wunde ausbreitet und außer Kontrolle gerät!\n\nNordrassil sollte fürs Erste wieder sicher sein. Es ist ein gutes Zeichen, dass es vielleicht doch möglich ist, den Schaden rückgängig zu machen, der Azeroth zugefügt wurde.\n\nGehen wir zurück zur Herzkammer und sehen wir, ob wir das Azerit, das Ihr absorbiert habt, sinnvoll einsetzen können.", sourceObjective = "Kehrt zur Herzkammer zurück.", completion = "Zusätzliches Azerit steht für das Herz von Azeroth zur Verfügung. Aktiviere es jetzt.", sourceObjectiveStatus = "unverified-source-field" }
quests[55522] = { id = 55522, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr zum Herzen", description = "Grüße, Champion von Azeroth.\n\nMUTTER hat Eure Fortschritte mit dem Herzen von Azeroth beobachtet und sie ist mit der Arbeit, die Ihr geleistet habt, um es stärker zu machen, sehr zufrieden.\n\nZumindest glauben wir das. Manchmal ist es schwer zu erkennen.\n\nEgal, kommt einfach zurück in die Herzkammer, sobald Ihr könnt. Es gibt noch viel zu tun.", sourceObjective = "Kehrt zur Herzkammer zurück.", completion = "Das Herz von Azeroth fühlt sich stärker an als je zuvor. Ich frage mich, was für Kräfte noch darin verborgen liegen!", sourceObjectiveStatus = "unverified-source-field" }
quests[55523] = { id = 55523, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bringt es ihm...", description = "<Mrrl zeigt auf Euren Rucksack und malt dann etwas in den Sand. Er holt einen schönen Gegenstand hinter einem Felsen hervor, zeigt dann wild fuchtelnd auf sich selbst, dann zu Euch und dann auf Eure Tasche.\n\nIhr glaubt, er möchte einen Tausch vorschlagen.>", sourceObjective = "Findet Murlochändler und holt Euch die Dinge, die Mrrl braucht.", sourceObjectiveStatus = "unverified-source-field" }
quests[55524] = { id = 55524, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bringt es ihm...", description = "<Mrrl zeigt auf Euren Rucksack und malt dann etwas in den Sand. Er holt einen schönen Gegenstand hinter einem Felsen hervor, zeigt dann wild fuchtelnd auf sich selbst, dann zu Euch und dann auf Eure Tasche.\n\nIhr glaubt, er möchte einen Tausch vorschlagen.>", sourceObjective = "Bringt Mrrl 5 Geisteressen, 5 stinkende Haufen Glibber und 5 Meeresriesenfußdreck.", sourceObjectiveStatus = "unverified-source-field" }
quests[55525] = { id = 55525, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bringt es ihm...", description = "<Mrrl zeigt auf Euren Rucksack und malt dann etwas in den Sand. Er holt einen schönen Gegenstand hinter einem Felsen hervor, zeigt dann wild fuchtelnd auf sich selbst, dann zu Euch und dann auf Eure Tasche.\n\nIhr glaubt, er möchte einen Tausch vorschlagen.>", sourceObjective = "Bringt Mrrl 4 gesunde Murlocmahlzeiten, 3 Taschen mit wer weiß was und 6 Meeresriesenfußdreck.", sourceObjectiveStatus = "unverified-source-field" }
quests[55526] = { id = 55526, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bringt es ihm...", description = "<Mrrl zeigt auf Euren Rucksack und malt dann etwas in den Sand. Er holt einen schönen Gegenstand hinter einem Felsen hervor, zeigt dann wild fuchtelnd auf sich selbst, dann zu Euch und dann auf Eure Tasche.\n\nIhr glaubt, er möchte einen Tausch vorschlagen.>", sourceObjective = "Bringt Mrrl 15 extraschleimige Schnecken, 3 stinkende Haufen Glibber und 5 Geisteressen.", sourceObjectiveStatus = "unverified-source-field" }
quests[55527] = { id = 55527, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bringt es ihm...", description = "<Mrrl zeigt auf Euren Rucksack und malt dann etwas in den Sand. Er holt einen schönen Gegenstand hinter einem Felsen hervor, zeigt dann wild fuchtelnd auf sich selbst, dann zu Euch und dann auf Eure Tasche.\n\nIhr glaubt, er möchte einen Tausch vorschlagen.>", sourceObjective = "Bringt Mrrl 3 Geisteressen, 3 gesunde Murlocmahlzeiten und 3 Meeresriesenfußdreck.", sourceObjectiveStatus = "unverified-source-field" }
quests[55528] = { id = 55528, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Genug gespielt", description = "Seit wir hier angekommen sind, plündern die Troggs unsere Vorräte. Aber jetzt verfügen wir über Feuerkraft, sodass Ihr dem Treiben ein Ende bereiten könnt!\n\nLehren wir diese Troggs, sich von unseren Sachen fernzuhalten!", sourceObjective = "Tötet 12 Troggs.", completion = "Ihr habt Euch Euren Lohn wohl verdient, {race}!", sourceObjectiveStatus = "unverified-source-field" }
quests[55529] = { id = 55529, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kein Zurück", description = "<Der Murloc sieht hungrig aus. Neben ihm seht Ihr einige grobe Zeichnungen, die nach einer Einkaufsliste aussehen. Vielleicht könnt Ihr der Kreatur helfen?>", sourceObjective = "Bringt Mrrl eine süße Seegurke, eine unidentifizierbare Masse, einen flatulenten Fisch und ein schleimiges Nagaauge.", progress = "Findet Murlochändler und holt Euch die Dinge, die Mrrl braucht.", completion = "<Mrrl frisst das schleimige Nagaauge, quetscht den flatulenten Fisch, reibt die unidentifizierbare Masse an seine Füße und wirft die süße Seegurke.\n\nEr sieht zufrieden aus.>", sourceObjectiveStatus = "unverified-source-field" }
quests[55530] = { id = 55530, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein sicherer Ort", description = "<Der Murloc sieht ziemlich mitgenommen aus. Vielleicht ist er bei Euren Verbündeten in Neuheim besser aufgehoben.>", sourceObjective = "Begleitet Mrrl zurück nach Neuheim.", completion = "<Mrrl scheint sich in seinem neuen Zuhause wohlzufühlen, und seine Familie hat hier ebenfalls Zuflucht gesucht. Es ist unwahrscheinlich, dass Ihr diese neue Murlocplage beseitigen könnt.>", sourceObjectiveStatus = "unverified-source-field" }
quests[55531] = { id = 55531, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was wird abgebaut?", description = "<Obwohl sie schon ziemlich abgenutzt aussieht, scheint diese Spitzhacke noch tauglich zu sein. Vielleicht könnt Ihr etwas in der Nähe abbauen?>", sourceObjective = "Schließt das Salzsteinbuchtereignis ab.", progress = "Was habt Ihr für mich?", completion = "Na, was haben wir denn hier? Ein seltener Fund, in der Tat! \n\nSalzstein ist ziemlich instabil und sollte nur mit spezieller Ausrüstung abgebaut werden. \n\nUnd sogar dann stört der Abbau oft genug die Elemente. Also geht vorsichtig vor.", sourceObjectiveStatus = "unverified-source-field" }
quests[55533] = { id = 55533, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "MUTTER weiß es besser", description = "Jetzt, wo sich diese Kammer nicht mehr in ihre Bestandteile auflöst, können wir uns darum kümmern, das Herz stärker zu machen!\n\nMUTTER sagt, sie habe ihre raffinierten Berechnungen abgeschlossen. Sprecht mit ihr, Champion. Lasst uns herausfinden, ob wir das großartige Geschenk, das Azeroth Euch vermacht hat, noch weiter verstärken können.", sourceObjective = "Sprecht mit MUTTER in der Herzkammer.", progress = "Bericht: Bereit für Dissemination.\n\nReaktion des Champions: Kritisch.", completion = "Analyse abgeschlossen. Um die planetarische Auslöschung zu verhindern, muss das Herz von Azeroth verstärkt werden.\n\nZiel: Kompatible Essenzen ausfindig machen. Priorität: Kritisch.", sourceObjectiveStatus = "unverified-source-field" }
quests[55534] = { id = 55534, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rostbolzengrammophon", description = "<Das große Grammophon, das Ihr gebaut habt, ist stark genug, seine Musik im ganzen Rostbolzen erklingen zu lassen.\n\nJetzt müsst Ihr nur noch eine gute Stelle finden, um es aufzubauen.>", sourceObjective = "Stellt das Grammophon im Beschwipsten Tüftler, der Taverne im Rostbolzen, auf.\n\nBereitgestellter Gegenstand:", completion = "<Das sieht nach einem geeigneten Ort aus, um das Grammophon aufzustellen.>", sourceObjectiveStatus = "unverified-source-field" }
quests[55535] = { id = 55535, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Beschwipste Tüftler", description = "Die massive Rostbolzenzapfanlage, die Ihr gebaut habt, sollte genug Platz für alle Getränke des Rostbolzenwiderstands haben.\n\nFindet einen Ort im Rostbolzen, an dem Ihr sie aufstellen könnt, und sagt allen Bescheid, dass sie betriebsbereit ist!", sourceObjective = "Stellt die Rostbolzenzapfanlage im Beschwipsten Tüftler, der Taverne im Rostbolzen, auf.", completion = "Das sieht nach einem geeigneten Ort aus, um die Zapfanlage aufzustellen.", sourceObjectiveStatus = "unverified-source-field" }
quests[55558] = { id = 55558, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sicher ist sicher", description = "{name}, wir brauchen eine mächtige Waffe gegen die Naga, die den Gezeitenkonflux bewachen. Ich bin mir sicher, dass wir so eine Waffe in den Händen von Azsharas Dienern finden.\n\nDank unserer neuen Verbündeten kennen wir den Aufenthaltsort einer ihrer Hofdamen in den Ruinen von Zin-Azshari. Die Reise dorthin wird nicht ungefährlich, doch glücklicherweise unterhalten unsere Verbündeten in der Nähe eine Stellung, die wir als Basis nutzen können.\n\nIch habe den Ort auf Eurer Karte markiert. Trefft mich dort, sobald Ihr könnt.", sourceObjective = "Trefft Euch mit Shandris Mondfeder in Utamas Wehr.", completion = "Ja, das ist genau richtig. Von hier aus können wir uns gut verteidigen und haben sicheren Zugang zu den Ruinen.", sourceObjectiveStatus = "unverified-source-field" }
quests[55560] = { id = 55560, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Utamas Vergeltung", description = "Wir Ankoaner sind nur ein kleiner Stamm. Es gibt nicht mehr viele von uns.\n\nAn diesem Ort wimmelte es einst von Makrura. Das war vor Utama. Unser Stamm versuchte, sich hier vor den Naga zu verstecken, stieß aber auf die Makrura. Er fiel im Kampf gegen die Kil'karrok.\n\nWenn Ihr Eure Ergebenheit den Ankoanern gegenüber zeigen wollt, dann werdet zu einer rächenden Kraft im Andenken an Utama. Vernichtet die Makrura.", sourceObjective = "Tötet 10 Makrura.", completion = "Ihr erweist Utama große Ehre, indem Ihr seine Feinde tötet.", sourceObjectiveStatus = "unverified-source-field" }
quests[55561] = { id = 55561, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Überreste von Zin-Azshari", description = "Zin-Azshari, einst die Hauptstadt der Nachtelfenzivilisation, ging im Zuge der Zerschlagung verloren. Königin Azshara verriet ihr Volk und erlaubte es N'Zoth, sie zu verderben und in Naga zu verwandeln.\n\nJetzt regiert nur noch das Chaos in den Ruinen.\n\nWir müssen uns ansehen, was aus der Stadt geworden ist. Trefft mich bei der Statue von Azshara.", sourceObjective = "Trefft Shandris bei der Statue von Azshara.", completion = "Ihr müsst noch tiefer in die Stadt vorstoßen.", sourceObjectiveStatus = "unverified-source-field" }
quests[55565] = { id = 55565, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Manareserven sammeln", description = "Nicht einmal mit dem Gezeitenstein war das Zurückhalten der Gezeitenwälle eine einfache Aufgabe. Der Fluss der magischen Energien ist in diesem Gebiet einfach zu unstet.\n\nWir müssen unsere magischen Reserven sammeln und dazu brauchen wir so etwas wie Manabatterien. Die beschmutzten Elementare entlang des Kanals sind mit genau solchen Elementarkernen erschaffen worden, wie wir sie brauchen.\n\nWir können hier zweierlei erreichen: Zum Einen entfernen wir die beschmutzten Elemente, bevor sich ihre Verderbnis ausbreitet und zum Zweiten erhalten wir die Elementarkerne, mit denen wir das Wasser in Schach halten können.", sourceObjective = "Sammelt 10 Elementarkerne.", progress = "Wie läuft die Jagd?", completion = "Wir bringen sie zurück zu Admiral Prachtmeer.", sourceObjectiveStatus = "unverified-source-field" }
quests[55569] = { id = 55569, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Echos des Schmerzes", description = "Diese Geister... das sind Hochgeborene. Sie standen Azshara sehr nahe. Azshara umgab sich mit vielen Günstlingen, aber dies waren ihre Lieblinge.\n\nIch weiß nicht, warum ihre Geister hier sind. Wir sollten das weiter untersuchen. Schaut, ob Ihr mit ihnen kommunizieren könnt, und findet heraus, warum sie an diese Ruinen gebunden sind.\n\nWie konnte sie diese armen Seelen nur verlassen?", sourceObjective = "Sprecht mit den Geistern, die durch die Anwesen der Hochgeborenen wandeln.", completion = "Ich habe solches Mitleid für diese Geister. Sie sind für immer an diesen Ort gebunden und müssen die schlimmsten Momente ihres Lebens immer wieder durchmachen.", sourceObjectiveStatus = "unverified-source-field" }
quests[55570] = { id = 55570, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geheimnisse der Ruinen", description = "Dies war einst ein Ort großer Macht. Die Hochgeborenen lebten hier im Überfluss und richteten opulente Feste aus.\n\nZin-Azshari befand sich einst an den Gestaden des Brunnens der Ewigkeit und lockte mächtige Magier aus dem ganzen Reich an, die hier studieren wollten. Ich vermute, dass hier auf dem Grund des Meeres trotz der vielen Jahre noch viele Schätze und mächtige Artefakte verborgen liegen.\n\nSprecht mit den hier verbliebenen Geistern, um etwas darüber herauszufinden. Es muss etwas geben, das uns hilft, die Wächterin des Gezeitensteins zu überwinden.", sourceObjective = "Sucht nach mächtigen Gegenständen.", completion = "Die Wurfspeere von Azshara? Davon habe ich noch nie etwas gehört. Oder sind das die Wurfspeere von Suramar? Das wäre dann in der Tat ein sagenhafter Fund!", sourceObjectiveStatus = "unverified-source-field" }
quests[55571] = { id = 55571, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Öffnet ihnen die Augen", description = "Die Informationen, die Ihr gesammelt habt, bereiten mir Sorgen, {name}. Diese Geister sind in den Ruinen, weil sie immer noch an Azshara und ihre Herrschaft glauben. Sie hat ihre Seelen an die Leere verkauft, aber die ruhelosen Geister sind ihr trotzdem noch treu.\n\nIch weiß, dass wir andere, drängendere Probleme haben, aber dennoch kann ich sie nicht so hier zurücklassen.\n\nZeigt es ihnen. Konfrontiert sie mit der Wahrheit und erzählt ihnen vom Verrat Azsharas.", sourceObjective = "Konfrontiert die Geister mit der Wahrheit über Azshara.", completion = "Viele der Geister, die Zin-Azshari heimsuchen, wissen gar nicht, dass sie tot sind. Sie wollen es sich nicht eingestehen.\n\nAber vielleicht können wir ihnen helfen... sofern Ihr bereit seid, mir zu helfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[55573] = { id = 55573, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Entfernt die Entweiher", description = "Azshara ging es immer nur um sie selbst. Alles musste ihren Namen tragen und ihren Ruhm mehren. Sie hat die Verbindung unseres Volkes zu Elune vergessen. Oder vielleicht hielt sie sie für unwichtig?\n\nAzshara und ihre Schergen haben diesen Ort zu lange mit ihrer schändlichen Ketzerei beschmutzt.\n\nLasst sie Elunes Rache spüren.", sourceObjective = "Tötet die Naga in Elun'alor.", completion = "Elunes Rache ist schnell und grimmig. Gut gemacht, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[55574] = { id = 55574, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Wurfspeere von Azshara.", description = "Diese Geister sprechen ständig von den Wurfspeeren von Azshara. Ich dachte zuerst, sie meinen die Hofdamen, die sich in Elun'alor verschanzt haben.\n\nAber... jetzt glaube ich, sie meinen die Wurfspeere von Suramar. Diese waren einst mächtige Waffen und galten lange Zeit als verschollen. Azshara beansprucht gern solche Dinge für sich.\n\nWir müssen ihre Hofdame in Elun'alor so oder so beseitigen. Wenn wir dabei einen der Wurfspeere finden, wäre das eine besonders glückliche Fügung des Schicksals.", sourceObjective = "Tötet die Hofdame von Azshara.", progress = "Wenn wir ihre Hofdamen getötet haben, werden sich die Naga aus Zin-Azshari zurückziehen.", completion = "Das Töten einer Hofdame allein wäre schon ein großer Erfolg gewesen, aber dazu auch noch ein Wurfspeer von Suramar? Heute wendet sich das Blatt. Heute haben wir den Weg zum Sieg eingeschlagen.", sourceObjectiveStatus = "unverified-source-field" }
quests[55575] = { id = 55575, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Des einen Gnoms Müll", description = "Der Kram in diesem Müllhaufen steckt voller seltener Metalle: Dalaranium, Suramit und sogar Gnomisium!\n\nSo leicht konnte ich kein Gold mehr verdienen, seit sie in Boralus vergessen hatten, die Tresortür abzuschließen. Helft mir, ein paar dieser seltenen Metalle einzusammeln. Mein Freund Gao wird sie dann auf dem Schwarzmarkt verkaufen.\n\nIch habe ein Gerät, mit dem man die Metalle direkt aus dem Haufen herausziehen kann!", sourceObjective = "Sammelt 100 seltene Metalle mit dem Metallsammler für seltenes Metall.", progress = "Hier gibt es Gold zu verdienen!", completion = "Das wird sich schnell verkaufen. Hier ist Euer Anteil am zukünftigen Profit!", sourceObjectiveStatus = "unverified-source-field" }
quests[55578] = { id = 55578, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tol Dagor: Juwel der Gezeiten", description = "<Beim Betrachten des Schreins vor Euch müsst Ihr seine faszinierende Bauweise einfach bewundern.\n\nDie nahtlose Konstruktion zeigt ein Strahlenmuster aus azurblauen Edelsteinen, die an einem einzelnen Punkt zusammenlaufen.\n\nAn einem einzelnen leeren Punkt. Ihr seid überzeugt, dass hier etwas fehlt. Rasch sucht Ihr den Bereich nach etwas Passendem ab, doch ohne Erfolg.\n\nAber ein Betrunkener macht hier am Schrein mit seinem Gegröle auf sich aufmerksam. Vielleicht weiß er etwas über den Verbleib des fehlenden Teils.>", sourceObjective = "Sprecht mit dem \"Aalglatten\" Johann und versucht, etwas über das fehlende Herzstück in Erfahrung zu bringen.", progress = "<Vielleicht kommt Ihr ja hinter die Funktionsweise des Schreins, wenn Ihr das fehlende Herzstück entdeckt?>", completion = "<Als Ihr den Edelstein wieder in der Mitte des Schreins befestigt, entspringt diesem ein merkwürdiger Impuls.\n\nDer wiederhergestellte Schrein beginnt, vor Energie zu summen.>", sourceObjectiveStatus = "unverified-source-field" }
quests[55579] = { id = 55579, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unter der Oberfläche", description = "<Bei Eurer Untersuchung bemerkt Ihr, dass der Schrein mehrere Stellen aufweist, an denen früher offenbar Juwelen angebracht waren.\n\nZudem scheint das Juwel in der Mitte bereits einige Risse aufzuweisen.\n\nIn Euren Notizen lest Ihr, dass der Irdene die Juwelen in einem nahen Berg im Nordwesten abgebaut hat.\n\nVielleicht könnt Ihr den Boden dieses Gebiets sondieren, um mehr von den Juwelen zu finden.>", sourceObjective = "Geht zu den Windgeschorenen Hügeln und sammelt 20 Goldberyllsplitter.", progress = "<Die Juwelen an diesem Schrein wurden auf ziemlich komplizierte Weise angeordnet.>", completion = "Ihr bringt die Juwelen vorsichtig mit Euren Werkzeugen in die richtige Form und befestigt sie an den leeren Plätzen am Schrein.\n\nMit den übrigen Juwelen gelingt es Euch, die Risse im Edelstein in der Mitte so auszubessern, dass er schließlich wieder über eine glatte Oberfläche verfügt.\n\nAls Ihr das letzte Juwel platziert, entweicht dem Schrein ein Energieimpuls und es scheint, als würde er das Licht aus der Umgebung in sich hineinziehen. Das merkwürdige Leuchten, das vom Inneren des Schreins ausgeht, lässt Euch vermuten, dass er wieder aktiv ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[55580] = { id = 55580, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Höhensondierung", description = "<Bei der Untersuchung des Schreins bemerkt Ihr, dass mehrere der in die Oberfläche eingesetzten Juwelen zerbrochen sind und ausgetauscht werden müssen.\n\nNach einem Blick in Eure Notizen erfahrt Ihr, dass der Irdene die Juwelen aus Erdelementaren im Süden extrahiert hat.\n\nNach einem Blick auf Eure Karte fragt Ihr Euch, ob er die heutigen Ruinen einer einst uralten Siedlung meinte, die jetzt mit Konstrukten und Untoten übersäht ist.\n\nVielleicht findet Ihr dort Hinweise darüber, wo Ihr diese Juwelen findet.>", sourceObjective = "Untersucht Gol Osigr auf Hinweise zu den Juwelen, mit denen der Schrein gebaut wurde.", progress = "<Es müssen definitiv alle zerbrochenen Juwelen ausgetauscht werden.>", completion = "<Ihr beginnt, alle zerbrochenen Juwelen vom Schrein zu entfernen und die neuen vorsichtig einzusetzen.\n\nAls Ihr das letzte einsetzt, entweicht dem Schrein ein Impuls und es scheint, als würde er das Licht aus der Umgebung in sich hineinziehen.\n\nDas merkwürdige Leuchten, das vom Inneren des Schreins ausgeht, lässt Euch vermuten, dass er wieder aktiv ist.>", sourceObjectiveStatus = "unverified-source-field" }
quests[55581] = { id = 55581, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sonnengesprenkelte Dünen", description = "<Beim Untersuchen des Schreins vermutet Ihr, dass es der sandige Wind in diesem Gebiet gewesen sein muss, der die eingesetzten Edelsteine so verwittert hat, dass einige nun merkwürdige Formen und Risse aufweisen.\n\nIn Euren Notizen steht, dass der Irdene an Dünen vorbeikam, in denen orangefarbene Edelsteine verstreut lagen, die ihn an das sanfte Sonnenlicht in dieser Gegend erinnerten.\n\nLaut Euren Notizen sollten sich diese Dünen südlich Eurer derzeitigen Position befinden.>", sourceObjective = "Begebt Euch zu dem auf Eurer Karte markierten Ort, an dem Ihr die Edelsteine vermutet, und sammelt 8 von ihnen. Schleift und poliert sie, wenn Ihr genug gesammelt habt.", progress = "<Diese Edelsteine haben eine sehr robuste Struktur. Die Zeit und auch der Wind müssen trotzdem ihren Tribut von ihnen gefordert haben.>", completion = "<Vorsichtig entfernt Ihr die alten, verwitterten Edelsteine aus dem Schrein und ersetzt sie mit den von Euch polierten.\n\nAls Ihr den letzten Stein einsetzt, entweicht dem Schrein ein Energieimpuls und es scheint, als würde er das Licht aus der Umgebung in sich hineinziehen. Das merkwürdige Leuchten, das vom Inneren des Schreins ausgeht, lässt Euch vermuten, dass er wieder aktiv ist.>", sourceObjectiveStatus = "unverified-source-field" }
quests[55582] = { id = 55582, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Atal'Dazar: Nicht alles, was glänzt...", description = "<Während Ihr den Schrein betrachtet, wird Euch klar, dass das zentrale Juwel schwer beschädigt ist und ersetzt werden muss.\n\nIhr seht in Euren Notizen über den Schrein nach und erfahrt, dass dieser Edelstein aus einem \"goldenen Refugium\" stammt.\n\nAusgehend von Eurem Standort kann damit nur Atal'Dazar gemeint sein. Vielleicht könnt Ihr in dieser uralten Stadt einen Ersatz finden.>", sourceObjective = "Reist nach Atal'Dazar und sucht einen Ersatz für das zerbrochene Juwel.", progress = "<Nachdem Ihr den zentralen Edelstein ausgetauscht habt, denkt Ihr, dass Ihr den alten vielleicht noch verkaufen könnt.>", completion = "<Ihr kehrt zurück zum Schrein und beginnt, den alten Edelstein aus seinem Sockel zu entfernen. Dabei bricht er erneut und zersplittert in Euren Händen.\n\nDie Steine sind offensichtlich sehr viel zerbrechlicher, als Ihr anfangs gedacht hattet.\n\nMit größter Vorsicht fügt Ihr das Juwel, das Ihr gefunden habt, in den Sockel ein.\n\nSobald Ihr ihn befestigt habt, geht ein friedvolles Leuchten vom Schrein aus. Dies lässt Euch vermuten, dass er wieder aktiv ist.>", sourceObjectiveStatus = "unverified-source-field" }
quests[55583] = { id = 55583, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aus Alt mach Neu", description = "<Bei der Untersuchung des Schreins bemerkt Ihr etwas, das Euch... vertraut erscheint. Der Schliff der Edelsteine wirkt wie eine primitive oder einfache Version der Art, wie Ihr Granat zu schleifen gelernt habt.\n\nOffensichtlich hat die Zeit aber ihre Spuren an ihnen hinterlassen. Einige sind stellenweise zerfressen und abgeplatzt.\n\nDie Reparatur des Schreins könnte sich tatsächlich als einfach erweisen: ein simpler Austausch der alten Edelsteine gegen neue desselben Typs und Schliffs.>", sourceObjective = "Schleift 4 treibende Granate und tauscht die alten gegen neue aus.", progress = "<Ihr findet es interessant, dass der Schliff so ähnlich ist, und Ihr fragt Euch, wie das Design die ganzen Jahre überdauern konnte.>", completion = "<Beim Austausch passen alle neuen Edelsteine perfekt in die Sockel, was Eure Vermutung über ihre Ähnlichkeit bestätigt.\n\nAls Ihr den letzten Edelstein einsetzt, entweicht auch diesem Schrein der vertraute Impuls und das Leuchten, das von ihm ausgeht, versichert Euch, dass er wiederhergestellt ist.>", sourceObjectiveStatus = "unverified-source-field" }
quests[55585] = { id = 55585, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein vielversprechender Anfang", description = "<Jetzt da der Schrein repariert ist, seid Ihr sehr begierig, den nächsten Schrein aufzusuchen.\n\nVielleicht hat Samuel noch weitere Standorte gefunden.>", sourceObjective = "Kehrt zu Samuel D. Kaltmann III. nach Boralus zurück und berichtet ihm von Eurer Entdeckung.", completion = "<Ihr berichtet Samuel von Euren Untersuchungen des Schreins der Stürme.>\n\nUnd Ihr konntet den Schrein reparieren? Das sind hervorragende Neuigkeiten. Vielleicht befinden sich die anderen beiden in einem ähnlichen Zustand, bedenkt man ihr Alter und dass sie möglicherweise nicht genutzt wurden.", sourceObjectiveStatus = "unverified-source-field" }
quests[55586] = { id = 55586, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufpoliert", description = "<Samuel würde sicherlich gerne mehr über Eure Fortschritte bezüglich dieses Schreins erfahren.\n\nIhr seid der Ansicht, dass Ihr ihm so bald als möglich Bericht erstatten solltet.>", sourceObjective = "Kehrt zu Samuel D. Kaltmann III. nach Boralus zurück und berichtet ihm von Eurer Entdeckung.", completion = "<Ihr berichtet Samuel von Euren Entdeckungen am Schrein in Drustvar.>\n\nEs ist wirklich ein Glücksfall, dass die Bewohner jener Gegend das selbe Gestein verwendet haben, um ihre Konstrukte zu erschaffen.\n\nEs scheint, dass bei unserer Suche nach den Schreinen das Glück auf unserer Seite ist.", sourceObjectiveStatus = "unverified-source-field" }
